quests[3884] = { id = 3884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Williden's Journal", description = "You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the northern part of the Crater; according to the journal, he and his companions sought higher ground from the savage beasts of the Crater once their base camps were overrun.", sourceObjective = "Return the journal to Williden Marshal somewhere in Un'Goro Crater.", progress = "Hello there!  I and my companions are happy to see some living beings here other than overgrown savage beasts!  What brings you into the Un'Goro Crater?", completion = "Well look at this - my journal!  I thought it was lost, much like almost everything else we brought into Un'Goro.  I thank you kindly for returning this to me!", sourceObjectiveStatus = "unverified-source-field" }
quests[3901] = { id = 3901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattling the Rattlecages", description = "You've shown your potential to the Forsaken under normal circumstances {name} - now let's see you under pressure.\n\nThe Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far.  Again, thin their numbers and prove yourself to the Forsaken.  Do not tarry - when you are done, speak to me again.", sourceObjective = "Kill 8 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done.", progress = "Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village.  Let's hope you will fare better than them, yes?", completion = "I am finished with you, {name} - you have shown yourself to be worthy of the freedom that you have been given.  Many will stand against you for what you have become, but know that no matter what they may try to do against us, we are free and will not be shackled again.\n\nTake these and be on your way.  You have much to accomplish, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[3902] = { id = 3902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scavenging Deathknell", description = "You there!  If you're looking for something to make yourself useful, then listen up!\n\nWe need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment.  Most likely, they'll be in stacks of boxes.  We expect more recruits to be rising soon, and unless we want them to stumble about naked we had better get to scavenging!\n\nWell get to work, you miserable bag of bones!  I'm not going to reward those without some hustle.", sourceObjective = "Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.", progress = "Have you managed to scavenge up some useful items for us?  There is no shame in reusing that which has been tossed aside.  No one is going to give us any handouts - we Forsaken will fend for ourselves!", completion = "Great work {name}, I knew you weren't useless.  Here - have one of the better items I've found out of the lots that have been collected so far.", sourceObjectiveStatus = "unverified-source-field" }
quests[3903] = { id = 3903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Milly Osworth", description = "You've shown yourself a dependable {class}, {name}.  Dependable, and not afraid to get your hands dirty, eh?\n\nI have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.", sourceObjective = "Speak with Milly Osworth.", completion = "Oh, Deputy Willem told you to speak with me?  He's a brave man and always willing to help, but his duties keep him stuck at Northshire Abbey and I'm afraid the problem I have today is beyond him.\n\nPerhaps you can help me?", sourceObjectiveStatus = "unverified-source-field" }
quests[3904] = { id = 3904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Milly's Harvest", description = "A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.\n\nPlease, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.\n\nBring me those buckets!  Save my harvest!", sourceObjective = "Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.", progress = "Do you have my harvest, {name}?", completion = "Oh thank you, {name}!  You saved my harvest!  And I hope you showed a few of those Defias that they can't cause trouble around here.\n\nWe might be short on guards these days, but we're lucky to have heroes like you to protect us!", sourceObjectiveStatus = "unverified-source-field" }
quests[3905] = { id = 3905, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grape Manifest", description = "Now that my crop is saved, take this Grape Manifest to Brother Neals.  He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes.\n\nYou'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.", sourceObjective = "Bring the Grape Manifest to Brother Neals in Northshire Abbey.", progress = "You look to be in fine spirits!  Come!  Have a seat, and have a drink!", completion = "Let's see here...\n\nOh my!  Milly's grapes have been saved!  When she told me that brigands overran her vineyards I nearly despaired, but my faith in the Light did not waver!\n\nAnd through your bravery,  we now have grapes for more wine!  May the Light bless you, {name}, and keep you safe!", sourceObjectiveStatus = "unverified-source-field" }
quests[3906] = { id = 3906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disharmony of Flame", description = "The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated.\n\nTravel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron.\n\nEnd the disruption and return to me.", sourceObjective = "Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.", progress = "The elements are still in disarray, {name}.", completion = "This cannot be... it must not be. The destruction of Pyron has merely lifted a veil. Within the depths of Blackrock is a much more insidious source of corruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[3907] = { id = 3907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disharmony of Fire", description = "I can taste the foulness in the air that surrounds you, {name}. There is another, hidden in the depths of Blackrock, who does control this foulness.\n\nThe wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary.\n\nFind him and discover where his master hides. Return to me when you have collected this information.", sourceObjective = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.", progress = "The flames will soon overtake these lands. Make haste, {name}!", completion = "<Thunderheart clutches the Tablet of Kurniya.>\n\nRagnaros... here...\n\nThe elders were right to fear the corruption emanating from Blackrock Mountain. A general of the Old Gods! IN OUR WORLD! We must reassess our position here in Kargath. We must decide on whether we stay and fight or run for fear of a new sundering.\n\nBe wary of any further exploration in Blackrock Mountain, {name}. A far greater evil than anything that exists in this world resides in those fiery depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[3908] = { id = 3908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Secret to Everybody", description = "You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything...\n\nThese items you brought to me, though... I am remembering something.\n\nMy sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember!\n\nAnyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there.", sourceObjective = "Take Linken's Sword to Donova Snowden in Winterspring.", progress = "My, my... So Linken did finally get around to sending me his sword.", completion = "Well, of course I can temper this sword. While I'm working, you can explain what took Linken so long to get this to me. He's not usually one to forget things...", sourceObjectiveStatus = "unverified-source-field" }
quests[3909] = { id = 3909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Videre Elixir", description = "Now, what's this? Linken... FORGOT?\n\nOh, I see... Lost his memory...\n\nWell, here is his sword. It's not complete, though. I know of the one that can finish it, but... speaking with him may prove difficult.\n\nListen, I know of someone that will be able to help you. It's too much to explain right now, but you must somehow acquire a Videre Elixir. The only one I know that can help you with that is Gregan Brewspewer. He's hard to track down, but last I knew he was camping in the wilds of Feralas.", sourceObjective = "Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.", progress = "Back already?", completion = "I'll need one vial to make sure that this is truly the elixir... Yes... This is the stuff.", sourceObjectiveStatus = "unverified-source-field" }
quests[3911] = { id = 3911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Element", description = "There is work to be had for those venturing into the depths, {name}.\n\nThe Dark Irons have mastered creation of extremely powerful golems.\n\nInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.\n\nJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.", sourceObjective = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", sourceObjectiveStatus = "unverified-source-field" }
quests[3912] = { id = 3912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet at the Grave", description = "This elixir will allow you to speak with one that you would not normally even see...\n\nTake the Videre elixir, along with Linken's sword, to the graveyard just outside Gadgetzan in Tanaris. Once there, drink the potion. You may be quite surprised at the results, but do not be alarmed.\n\nIn your \"other\" form, head due north until you reach the mountains. You'll find the one you need to speak with in one of the rocky crevices. His name is Gaeriyan.\n\nRemember, he will only speak to you in that form...", sourceObjective = "Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.\n\nProvided item:", completion = "It has been long since any have come to talk with me...", sourceObjectiveStatus = "unverified-source-field" }
quests[3913] = { id = 3913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grave Situation", description = "If you return to the graveyard, {name}, you will find a gravestone there... Not just any gravestone; this one will stand out from the others. Secrets lie within it.\n\nPush on the stone, and you will learn of these secrets...", sourceObjective = "Resurrect, then look for the gravestone that Gaeriyan told you to find.", progress = "This must be the gravestone that Gaeriyan mentioned...", completion = "You push on the stone firmly, and it slides away, revealing a small depression underneath it.\n\nPlacing Linken's Sword into the depression, you realize that it fits perfectly...", sourceObjectiveStatus = "unverified-source-field" }
quests[3914] = { id = 3914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linken's Sword", description = "After a strong flash of light, you are able to pick up the sword again. It has been transformed!", sourceObjective = "Deliver Linken's Superior Sword to Linken in Un'Goro Crater.", progress = "Oh! I remember you! You are... No, don't tell me!", completion = "My sword... It's finished!\n\nNow, if only I could remember why I needed this...\n\nHere, let me at least pay you for your work.", sourceObjectiveStatus = "unverified-source-field" }
quests[3921] = { id = 3921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenikee Boltbucket", description = "I think I might have broken that Samophlange.  That's not good, because I already told some colleagues in Undermine about it and they were very intrigued.  We must find a way to fix it!\n\nTake the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, the horde outpost between the Barrens and Ashenvale.  She is very clever and inquisitive.  If you show her the samophlange I bet she'd jump at the chance to fix it.", sourceObjective = "Bring the Broken Samophlange to Wenikee Boltbucket.", progress = "I'm very busy with my work, {class}.  Unless you have something for me, it'd be best if you moved along...", completion = "Oh, what's this?  A samophlange, you say?  What's a samophlange??\n\nAh... but look at the way it moves when you handle it.  And there's the sound of intricate gears inside.  Oh my!  I want to fix it and see what it does, don't you??", sourceObjectiveStatus = "unverified-source-field" }
quests[3922] = { id = 3922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nugget Slugs", description = "I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.\n\nThe closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs.", sourceObjective = "Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.", progress = "Do you have the nugget slugs, {name}?  I've been eyeing this Samophlange and I can't wait to tinker with it.", completion = "Great, you got them!  Now I can get to work...", sourceObjectiveStatus = "unverified-source-field" }
quests[3923] = { id = 3923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rilli Greasygob", description = "Well, that didn't work.  I put some extra gauges on the samophlange to measure its structural integrity, and they read the integrity at an all-time low.  I could add some more dials and maybe a lever or two to try and fix it, but... I think that might make things even worse.\n\nYou should take the samophlange to Rilli Greasygob.  He used to work for the Venture Company -- if anyone knows how to fix it, it's Rilli.\n\nYou can find him at Nogg's Machine Shop in Orgrimmar, in the Valley of Honor.", sourceObjective = "Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar.", progress = "Mind your head!  I don't want it to get in the way of my work!", completion = "What's this?  Why, it's a samophlange!  Where did you get this thing?  Have you been poking around the Venture Company holdings in the Barrens?\n\nYou must be very brave, or very stupid.", sourceObjectiveStatus = "unverified-source-field" }
quests[3924] = { id = 3924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Samophlange Manual", description = "I think I can fix the samophlange, but I'm going to need the user's manual first.  When I was in the Venture Company I had a rival, Boss Copperplug, who hoarded the secrets of the samophlange, giving out small bits of knowledge on the device to those he trusted.  I wasn't one of the trusted few...\n\nBoss Copperplug used to stay at the Boulder Lode Mine in northeastern Barrens.  Get the manual from him, and if he's given pages from it to anyone, you'll have to collect them too.", sourceObjective = "Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.", progress = "Do you have the manual?", completion = "You got the manual!  I can't wait to read it and find out how to fix the Samophlange!  I spoke with Sputtervalve in Ratchet--he wanted to thank you for your help, and wanted to reward your efforts.\n\nI want to thank you too, and if I ever get this thing fixed I'll let you know...", sourceObjectiveStatus = "unverified-source-field" }
quests[3941] = { id = 3941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gnome's Assistance", description = "Thinking... Thinking... I know I came here for something important...\n\nI have an idea, {name}. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her.\n\nWhy don't you go ask her if she knows anything? Oh, but be careful -- she's always messing with those crazy glowing crystals I've seen in the crater. I'm not quite sure what she's up to in there!", sourceObjective = "Find J.D. Collie in the cave at Marshal's Refuge.", completion = "Stay where you are for just a moment... I am testing out a new combination of crystals...", sourceObjectiveStatus = "unverified-source-field" }
quests[3942] = { id = 3942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linken's Memory", description = "Oh... Linken? Yeah, he's a funny one. When he first got here, he was mumbling about all kinds of strange things. Probably got bumped on the head pretty hard, I imagine.\n\nSomething he said kinda stuck with me though -- that he was making some sort of totem; said he had to talk to someone named Eridan Bluewind... in a place called Felwood, I think?\n\nI doubt he could tell you much now, though. If you want to know more, maybe you should look for Eridan yourself?", sourceObjective = "Find Eridan Bluewind in southern Felwood.", completion = "Hello, {class}. Is there something I can help you with?", sourceObjectiveStatus = "unverified-source-field" }
quests[3961] = { id = 3961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Linken's Adventure", description = "To think all this time that the reason Linken came here was to rid us of Blazerunner... He seems like such an ordinary guy, but I did notice that he's not at all interested in any of my experiments or gadgets like most gnomes would be. He must be a true warrior at heart.\n\nBring the totem to him. See if that helps him remember why he came here.", sourceObjective = "Take the Silver Totem of Aquementas to Linken in Marshal's Refuge.", progress = "Hi, again, {name}!", completion = "Did J.D. help you at all?", sourceObjectiveStatus = "unverified-source-field" }
quests[3962] = { id = 3962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Dangerous to Go Alone", description = "{name}, I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step.\n\nBut I am no longer the hero... You are. All that you have done -- you must finish this now, not me.\n\nBlazerunner guards an artifact called the Golden Flame. It provides power more vast than anything else I have ever known, and it is dangerous in the hands of one with an evil heart.\n\nYou will want to bring others with you -- it's dangerous to go alone. Take this as my advice.", sourceObjective = "Travel to Fire Plume Ridge, south of Marshal's Refuge.\n\nFind Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.", progress = "Blazerunner is almost invincible behind the aura he has created by using the Golden Flame. Only you have the power to remove it with the Silver Totem of Aquementas.", completion = "Thank you, {name}.\n\nThe Golden Flame will now be returned back to my homeland, where it may be protected, never again to be used for evil.\n\nWithout you, I'd still have no idea who I am! Since you did so much for me, I'd like you to have something special...\n\nTake any one you want!", sourceObjectiveStatus = "unverified-source-field" }
quests[3981] = { id = 3981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander Gor'shak", description = "Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now...\n\n<Galamav grimaces.>\n\nWhen we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached.\n\nIf he's still alive in the Depths, you'll have to find him.\n\nA trap you say? Well no kidding, numb hooves! That's why you're going!", sourceObjective = "Find Commander Gor'shak in Blackrock Depths.\n\nYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.", completion = "We haven't got much time. Listen carefully, {race}. What I have to tell you is classified and for your ears only.", sourceObjectiveStatus = "unverified-source-field" }
quests[3982] = { id = 3982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is Going On?", description = "I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence.\n\n<Gor'shak whispers.>\n\nThe Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news.\n\n<Gor'shak laughs.>\n\nShhh! Do you hear that? Guards coming! DEFEND YOURSELF!", sourceObjective = "Defend Gor'shak.", progress = "Defend yourself, fool!", completion = "That was a close call. They have been alerted to your presence... more will surely come.", sourceObjectiveStatus = "unverified-source-field" }
quests[4001] = { id = 4001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is Going On?", description = "So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm.\n\nGo speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief.\n\nThrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go!", sourceObjective = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.\n\nYou recall Gor'shak mentioning that Kharan is being held in a cell nearby.", progress = "What brings you to these hallowed grounds?", completion = "This is a chance for the Horde to change the political climate of our war torn world forever. Listen carefully, {name}.\n\nFailure of this mission is not an option.", sourceObjectiveStatus = "unverified-source-field" }
quests[4002] = { id = 4002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Kingdoms", description = "You bring excellent information, {name}.\n\nAs Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence.\n\nThe opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail!\n\nAre you prepared?", sourceObjective = "Speak with Thrall if you are prepared to take on the mission he has planned.", completion = "There is no going back beyond this point, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4003] = { id = 4003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Royal Rescue", description = "This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.\n\nPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.\n\nDO NOT HARM HER!", sourceObjective = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.", completion = "What have you done!", sourceObjectiveStatus = "unverified-source-field" }
quests[4004] = { id = 4004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess Saved?", description = "You have slain my husband, {race}! My child will be born into this world without a father.\n\n<Princess Moira points directly at you.>\n\nI assure you, this child will be the next ruler of the kingdom of Ironforge. You and your kind shall be hunted down until the end of days for this wrongful act.\n\n<You think that Princess Moira may be suffering from the residual effect of Thaurissan's spell.>\n\nLeave me be, {race}. I am certain your warchief will be eager to hear the results of his meddling.", sourceObjective = "Return to Thrall at Grommash Hold in Orgrimmar.", completion = "<Thrall is taken aback by the information you have presented to him.>\n\nA new threat now looms on the horizon. As Magni's years dwindle down, the way shall be opened for this unborn Dark Iron to become ruler of Ironforge.\n\nYou have accomplished what I asked of you and for that, you shall be rewarded.\n\nNow leave me, {name}! I must confer with Sylvanas and Cairne.", sourceObjectiveStatus = "unverified-source-field" }
quests[4005] = { id = 4005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aquementas", description = "Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones.\n\nThe eastmost peninsula is the secret...\n\nFrom this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner.\n\nAquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items.", sourceObjective = "Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.\n\nUse the Book of Aquor to summon Aquementas.\n\nAfter you have the completed totem, take it to J.D. Collie in Marshal's Refuge.", progress = "So you're back, eh? Hmm... Let me take a look at that, {name}.", completion = "Blazerunner, you say...\n\nYes, I am aware that a strong elemental resides in the charred center of the crater. We all just keep our distance; none have been able to penetrate the powerful aura that surrounds him. Many have been pushed from the rocky paths onto the ground below when trying to face him.", sourceObjectiveStatus = "unverified-source-field" }
quests[4021] = { id = 4021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counterattack!", description = "The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!\n\nFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof.\n\nWe're counting on you, {name}.", sourceObjective = "Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.", progress = "Do you have the banner?", completion = "You have done it!  You have defeated the Kolkar!\n\nI will be sure Thrall receives word of your actions here, {name}.\n\nStand tall.  You do yourself, and the Horde, proud.", sourceObjectiveStatus = "unverified-source-field" }
quests[4022] = { id = 4022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Flame", description = "The flight is aware of your work in the Searing Gorge.\n\nShow it to me, {race}. The molt, imbecile.", sourceObjective = "Show Cyrus Therepentous the Black Dragonflight Molt you received from Velarok Windblade.", progress = "<Cyrus's eyes form two blazing spheres.>", completion = "<Cyrus examines the molt.>\n\nYou have proven that you are not entirely useless, mortal.", sourceObjectiveStatus = "unverified-source-field" }
quests[4023] = { id = 4023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Flame", description = "You seek out the Flight? Present to me proof of your worth, mortal.", sourceObjective = "Show Cyrus Therepentous proof of your worth.\n\nYou have a feeling that Cyrus already knows that you are unworthy.", progress = "<Cyrus's eyes form two blazing spheres.>", completion = "<Cyrus examines the molt.>\n\nYou have proven that you are not entirely useless, mortal.", sourceObjectiveStatus = "unverified-source-field" }
quests[4024] = { id = 4024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Flame", description = "I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave.\n\nBael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire.\n\nUse the molt on his remains to safely extract the inner flame.\n\nSucceed and be rewarded.", sourceObjective = "Travel to Blackrock Depths and slay Bael'Gar.\n\nYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\n\nReturn the Encased Fiery Essence to Cyrus Therepentous.", progress = "Has the giant been felled?", completion = "<Cyrus snatches the fiery essence from your hands.>\n\nYES!\n\nTake your prize and be gone. Leave my sight at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[4041] = { id = 4041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Videre Elixir", progress = "Bring me an Evoroot, and sure, I can make ya that Videre Elixir.\n\nI know all kinds of things about herbs and alchemy... Why, let me tell you the story about the time I transmuted gold from the cheese I was going to eat for lunch... hey... Where are you going?", completion = "So, you pulled a fast one on ol' Miblon, eh?" }
quests[4061] = { id = 4061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Machines", description = "The machines made themselves known to us during our initial forays into the Searing Gorge. Upon further investigation we discovered that they were being imported from Burning Steppes, possibly Blackrock Depths. That is what we need you for, {name}.\n\nYour first task is to venture to the Burning Steppes and recover elemental shards from the rock automatons and lesser rock creations of the region. Once you have collected a sufficient amount, return to me and I shall determine their source of origin.", sourceObjective = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.\n\nYou recall Theodora mentioning the golems and elementals of that region as being a source for these shards.", progress = "Do not take this task lightly, {name}!", completion = "<Theodora lays the fragments out before her.>\n\n<Theodora carefully examines the fragments with an enormous monocle.>\n\nInteresting. Etched into the structural foundation of each of these fragments are... initials.", sourceObjectiveStatus = "unverified-source-field" }
quests[4062] = { id = 4062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Machines", description = "G.L.A.\n\nThose are the 'initials' imprinted on the elemental shards. Below the initials are a rank marking of some sort. The machinations you destroyed in the Burning Steppes were of 'Rank IV.' I assume that this is a lowly rank.\n\nTake this shard sample to Lotwil Veriatus in the camp to the east. He is a scholar of some renown in the field of elemental sciences. He may be able to assist us in our search.", sourceObjective = "Take the Elemental Shard Sample to Lotwil Veriatus.\n\nYou recall Theodora saying that Lotwil was stationed in a camp to the east.", progress = "What have you got there, {race}?", completion = "<Lotwil's face turns white.>\n\nI... I know these markings.", sourceObjectiveStatus = "unverified-source-field" }
quests[4063] = { id = 4063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rise of the Machines", description = "This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him.\n\nHe was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs. It seems that the wicked always find a way to escape justice.\n\nIf this is Argelmach's handiwork then he must be destroyed. I will need samplings of his latest creations. With the proper samples, I may be able to stop this uprising. The creations guard Argelmach in Blackrock Depths.", sourceObjective = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", progress = "Was it him? Was he really alive?", completion = "What is this?!? This head is not flesh. This is some sort of dark iron creation: A shadow of Argelmach - ANOTHER machine! I suspect that your destruction of Argelmach will be short lived as another shall rise to take 'its' place soon.", sourceObjectiveStatus = "unverified-source-field" }
quests[4081] = { id = 4081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "KILL ON SIGHT: Dark Iron Dwarves", description = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nAny and all of General Angerforge's forces within Blackrock Depths must be annihilated.\n\nAngerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes.\n\nAny person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute.", sourceObjective = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.", completion = "This first strike should put a crease in Angerforge's pants. Now, move along soldier. I have work to complete, battles to plan, enemies to crush!\n\nCheck the wanted signs for more work.", sourceObjectiveStatus = "unverified-source-field" }
quests[4082] = { id = 4082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "KILL ON SIGHT: High Ranking Dark Iron Officials", description = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nHead of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them!\n\nCompletion of this mission will result in a tribute.", sourceObjective = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", completion = "Angerforge is undoubtedly... angry. Return to me when you receive a third tribute and we shall proceed with Operation: Death to Angerforge. I cannot go into any detail of what this entails, but rest assured, it involves somebody dying.", sourceObjectiveStatus = "unverified-source-field" }
quests[4083] = { id = 4083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spectral Chalice", progress = "The spectral chalice floats in the air, slowing rising and falling... as if to the beat of a dying heart.", completion = "The gems make no sound as they fall into depths of the chalice..." }
quests[4084] = { id = 4084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Heart", description = "I do not know the one you speak of, {name}.\n\nBut worry not; if your friend was on a journey to find me, I do know what it was he desired.\n\nIn the heart of Un'Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel...\n\nNone... except those with enough power to do so. I can teach you of this power, {name}.\n\nFirst, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then return.", sourceObjective = "Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.", progress = "I can tell you more of the power required to defeat Blazerunner, but first, you need to gather the things I require.", completion = "Very well, {name}. I can see you are serious about helping your friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[4101] = { id = 4101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Felwood", description = "Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!\n\nTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.", sourceObjective = "Bring 15 Blood Amber to Arathandris Silversky in Felwood.", progress = "I know Felwood suffers, {name} - I suffer along with it!  I must remain steadfast in my conviction; were the knowledge I possess to fall into the wrong hands, it would spell disaster for all of Felwood.\n\nBring to me the blood amber drawn from the slain Warpwood elementals, and I will trust you enough to help me enact a means to fight the corruption.", completion = "This blood amber will be used to find a means of defeating the corruption present in Felwood.  You've proven to me that you're willing to do whatever it takes for the Cenarion Circle.  I trust you now, friend.\n\nIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take.  You and I can now focus on the preservation of life through the salves I can make.\n\n{name}, the time has come to cleanse Felwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[4102] = { id = 4102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Felwood", description = "Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!\n\nTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.", sourceObjective = "Bring 15 Blood Amber to Maybess Riverbreeze in Felwood.", progress = "I know Felwood suffers, {name} - I suffer along with it!  I must remain steadfast in my conviction; were the knowledge I possess to fall into the wrong hands, it would spell disaster for all of Felwood.\n\nBring to me the blood amber drawn from the slain Warpwood elementals, and I will trust you enough to help me enact a means to fight the corruption.", completion = "This blood amber will be used to find a means of defeating the corruption present in Felwood.  You've proven to me that you're willing to do whatever it takes for the Cenarion Circle.  I trust you now, friend.\n\nIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take.  You and I can now focus on the preservation of life through the salves I can make.\n\n{name}, the time has come to cleanse Felwood.", sourceObjectiveStatus = "unverified-source-field" }
quests[4103] = { id = 4103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Hunting", progress = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", completion = "Very well then, here are your Cenarion plant salves.  Scour Felwood for corrupted plants, {name}!  Wherever they are, use the salve I have given you to purify them." }
quests[4104] = { id = 4104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Mining", progress = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", completion = "Very well then, here's some Cenarion plant salve.  If you find more vitriol when you mine in Felwood, remember to hold on to it for me!  The more of it you find, the more salve I will be able to make." }
quests[4105] = { id = 4105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Gathering", progress = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", completion = "Excellent work {name} - every bit of this, once we purify it, will help us take back Felwood.  Here, take some doses of Cenarion plant salve and head into the forest.  The reclaiming of the land from the corruption waits for no {race}!" }
quests[4106] = { id = 4106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Skinning", progress = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", completion = "This is exactly what I need.  Here - take these plant salves and use them to reclaim Felwood from the corruption.  We must persevere, {name}!" }
quests[4107] = { id = 4107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Disenchanting", progress = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", completion = "Here are some Cenarion plant salves - I only need one lesser nether essence for this, {name}.  Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were.  If you need more salve, then find me here!" }
quests[4108] = { id = 4108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Hunting", progress = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", completion = "Very well then, here are your Cenarion plant salves.  Scour Felwood for corrupted plants, {name}!  Wherever they are, use the salve I have given you to purify them." }
quests[4109] = { id = 4109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Mining", progress = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", completion = "Very well then, here's some Cenarion plant salve.  If you find more vitriol when you mine in Felwood, remember to hold on to it for me!  The more of it you find, the more salve I will be able to make." }
