quests[4113] = { id = 4113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4114] = { id = 4114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4115] = { id = 4115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4116] = { id = 4116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4117] = { id = 4117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Whipper Root", progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4118] = { id = 4118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4119] = { id = 4119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Night Dragon", progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant.  The fruits that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4120] = { id = 4120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strength of Corruption", description = "Being a hunter, I strive to emulate the strengths I see in my opponents. It is possible to turn the battle in your favor by simply knowing your enemy well, {name}.\n\nIn a place called Felwood, north of Ashenvale, the creatures have been tainted by a substance called fel. The bears and wolves have been driven mad by it, but I believe that they have also grown even stronger as well.\n\nGo, {name}. Travel to Felwood and face these beasts. Learn for yourself if they are truly as strong as I believe.", sourceObjective = "Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood.", progress = "Everything touched by the fel emanates a strange green glow... I sense it is evil, but at the same time, very powerful.", completion = "It sounds from your descriptions as if the creatures show a mindless ferocity...\n\nStay alert, {name}. It would be in your best interest to learn more of the corruption. Always know your enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[4121] = { id = 4121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Precarious Predicament", description = "Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?\n\nYou will be destroyed!", sourceObjective = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\n\nYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\n\nYou will also be required to hand over your Thorium Shackles to Lexlort.", progress = "I will take this traitorous filth, {name}.", completion = "Your heroics will not go unrecognized, {name}. You have earned this tribute. The Warlord will speak with you now in regards to the final mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[4122] = { id = 4122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grark Lorkrub", description = "I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.\n\nHe now sits in the Burning Steppes, safely under their protection - or so he thinks.\n\nTake these shackles, {name}. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours.", sourceObjective = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\n\nWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.\n\nProvided item:", completion = "Can you not see the power we gain by joining the legion of Blackrock?", sourceObjectiveStatus = "unverified-source-field" }
quests[4123] = { id = 4123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Mountain", description = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to the Lower Vault of Blackrock Depths, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", sourceObjective = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", progress = "Do you have the Heart of the Mountain?  To me, its value is without limit.", completion = "You have the heart!  Amazing!  It is even more beautiful than I imagined!\n\nPlease, {name}, take this as payment!", sourceObjectiveStatus = "unverified-source-field" }
quests[4124] = { id = 4124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Courier", description = "An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action.\n\nIf you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters.", sourceObjective = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.", completion = "Latro sent you to me, I presume.  While I think it is a lost cause at this point, I'll take whatever assistance you can offer.  I must admit... I'll be glad once I can put my mind to rest on this matter.  Every day I set out into the wilds of Feralas looking for signs of Raschal, and every night I have come back with nothing to show for my work save gnoll teeth and disappointment.", sourceObjectiveStatus = "unverified-source-field" }
quests[4125] = { id = 4125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Courier", description = "It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp.\n\nI couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know.", sourceObjective = "Locate the courier's boat somewhere along the coast of Feralas.", completion = "You have found what appears to be a wrecked row boat.  Through the slightly muddy water you see gaping holes riddling the port side; the boat is nearly shredded down to its simple wooden frame.  Whatever broke this boat most likely tried to snap it in two.  A small crest of the Feathermoon Stronghold is painted on the starboard side.\n\nIn the mud at the base of the boat, a glint of something metallic catches your eye...", sourceObjectiveStatus = "unverified-source-field" }
quests[4126] = { id = 4126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hurley Blackbreath", description = "The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager.  The villains!  They don't deserve such a fine brew!\n\n{name}, I have a tough task for you.  Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager!\n\nPlease, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!", sourceObjective = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.", progress = "Do you have the recipe, {name}?  I can't stand the idea of those Dark Iron dwarves drinking my family's drink!", completion = "You found it!  Well done!  And I hope you gave those Dark Irons, and Hurley Blackbreath, a good thumping!\n\nThe Thunderbrews are at your service, {name}.  You are a hero of heroes!", sourceObjectiveStatus = "unverified-source-field" }
quests[4127] = { id = 4127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boat Wreckage", description = "Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss.\n\nYou grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water...", sourceObjective = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.", progress = "Ah, welcome back {name}.  I hope that you were able to uncover some clue as to Raschal's ultimate fate, as tragic as that may be.", completion = "Interesting... I believe that this is Raschal's knife.  You say you found it at the bottom of the water, along with his boat?  Well, just the knife's discovery might not be enough to connect this to Raschal's disappearance; we do, however, have an unconventional option available to us to try and learn more.\n\nHave you ever heard of psychometry?", sourceObjectiveStatus = "unverified-source-field" }
quests[4128] = { id = 4128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragnar Thunderbrew", description = "Ho, {name}.  I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale.  He's looking for stalwart adventurers, and willing to pay plenty.\n\nTalk to Ragnar if you're interested.  He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh.", sourceObjective = "Speak with Ragnar Thunderbrew.", completion = "You're right I'm mad!  I've been robbed!  Robbed of one of our family recipes!  How dare they!  As if I didn't have enough cause to hate the Dark Iron dwarves!  Now, oh... now they're in for it!", sourceObjectiveStatus = "unverified-source-field" }
quests[4129] = { id = 4129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Knife Revealed", description = "The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me.\n\nTake the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife.", sourceObjective = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.", progress = "Ginro sent you, eh?\n\nMy psychometric readings are fairly draining on the psyche... but so are my losses at Kalimdor Hold 'Em.  They call me \"King of the Bad Beats\" here in the Stronghold.  Unlucky at cards... lucky at mastering the secrets of nature, I guess.\n\nAnyway, of course I'll do it.  This may be just the breakthrough we need to uncover Raschal's fate.  If you would hand me the knife, we can get started.", completion = "Thank you, {name}.\n\nWhile psychometry isn't an exact art by any stretch of the imagination, I've used it in times past to give insight into situations that others have chalked up to lost causes.  I think using it on the knife you've uncovered will give us a glimpse into what happened to Raschal.\n\nIt will only take a moment to do, but it isn't what I'd call a caster-friendly task.  Bear with me on this.", sourceObjectiveStatus = "unverified-source-field" }
quests[4130] = { id = 4130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Psychometric Reading", description = "I'm a little wobbly still, sorry.  Anyway, I received some useful visions.\n\nRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there.\n\nI need to rest, sorry {name}.  Tell Gin what I've seen.  He needs to know.", sourceObjective = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.", completion = "Thanks for passing along Quint's visions to me, {name}.  I'll try to remember to be a little easier on him the next time we play cards.\n\nRaschal can hold his own in a fight, and gnolls aren't anything that would get him worried - nay, terrified.  Still, maybe you and yours can act on this new information and make the breakthrough we desperately need.", sourceObjectiveStatus = "unverified-source-field" }
quests[4131] = { id = 4131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Woodpaw Gnolls", description = "Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking.\n\nI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them.", sourceObjective = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.", completion = "Tacked up on a nearby tree are two large leather backpacks.  Each bears a small insignia of the Feathermoon Stronghold on the front of the pack...", sourceObjectiveStatus = "unverified-source-field" }
quests[4132] = { id = 4132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Death to Angerforge", description = "You have done an exemplary job, {name}. It is now time to send you on your last mission.\n\nGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.\n\nThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded.", sourceObjective = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", progress = "Has the Butcher of Blackrock been disposed of?", completion = "Finally! The villain been brought to justice! You are a remarkable individual, {name}. Wear this medallion as a symbol of your stalwart dedication to the Horde and the K.E.F.", sourceObjectiveStatus = "unverified-source-field" }
quests[4133] = { id = 4133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vivian Lagrave", description = "Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.\n\nSpeak with Vivian.  She awaits you.", sourceObjective = "Speak with Shadowmaster Vivian Lagrave in Kargath.", completion = "Thank you for coming, {name}.  This place is not without a stark charm, but it lacks the amenities of the Apothecarium.\n\nEnough with the pleasantries.  To business, yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[4134] = { id = 4134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Thunderbrew Recipe", description = "It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.\n\nDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.\n\nAnd to find him, you may have to entice him by threatening his precious ale.", sourceObjective = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.", progress = "Do you have the recipe for the Thunderbrew Lager, {name}?", completion = "Very good.  I will send this recipe to the Apothecarium to be studied, and in time we will unlock its secrets.  One day, the dwarves of the Alliance may find the virtues of this drink used against them!\n\nI find that terribly amusing.  Perhaps death has an affect on one's sense of humor... do you think?", sourceObjectiveStatus = "unverified-source-field" }
quests[4135] = { id = 4135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Writhing Deep", description = "Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.\n\nThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".\n\nIt would seem that you have located where Raschal ultimately went.", sourceObjective = "Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep. According to the note, it is located to the south of the Woodpaw gnoll camps.\n\nProvided item:", completion = "You have discovered a large pod of an alien nature.  The texture of the pod appears mucous, though hardened protrusions stick out from random parts of it.  The pod itself has the height and width to easily encompass a humanoid inside of it... and from the faint humanoid shape visible through the skin of the pod, you surmise that this is what it indeed encapsulates.", sourceObjectiveStatus = "unverified-source-field" }
quests[4136] = { id = 4136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ribbly Screwspigot", description = "My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another.\n\nWell, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head.  I can't tell you how happy this makes the Screwspigots!  Our little Ribbly's finally worth something!\n\nBut now he's hiding out, deep in Blackrock Depths.  Please, find him and bring him to me!\n\nOr, if he won't come, then that's ok... just bring me his head.", sourceObjective = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.", progress = "Do you have Ribbly?  Or, at least a part of him?", completion = "Aha!  You found him!  And... it appears that my little brother didn't want to come quietly.  It's a pity.  I would have liked to see the look on his face when I told him our plans to turn him in to Revilgaz.\n\nThank you, {name}.  You've made my family very happy.  And Ribbly's never looked as peaceful as he does now.", sourceObjectiveStatus = "unverified-source-field" }
quests[4141] = { id = 4141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muigin and Larion", description = "See Larion over there? It's HIS fault we're here!\n\nI told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him.\n\nHave you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands.\n\nFirst thing though, I'll need some samples to study. Do you think you could collect some?", sourceObjective = "Collect 15 Bloodpetals and return to Muigin.", progress = "Larion's got something coming, that's for sure!", completion = "I hope they didn't give you too much trouble, {name}. I try to steer clear of them -- they're wild!\n\nI tried jumping over one... I was attacked! Plants just shouldn't be acting that way!", sourceObjectiveStatus = "unverified-source-field" }
quests[4142] = { id = 4142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Visit to Gregan", description = "I'm not quite sure what to make of this, {name}. The plants... they seem to have some minimal intelligence.\n\nI'm no expert, though. But, I do know someone that is!\n\nHead to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing.\n\nI'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city.", sourceObjective = "Take a Bloodpetal to Gregan Brewspewer in Feralas.", progress = "I live out here in the forest... Peaceful.\n\nWell, at least I thought it would be. I get more visitors out here than I ever did when I lived in Ironforge!", completion = "Bloodpetal, eh? Hmmm... Well, you better explain the plan, and then I'll tell you whether or not I can help you.", sourceObjectiveStatus = "unverified-source-field" }
quests[4143] = { id = 4143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haze of Evil", description = "To tell you the truth, {name}, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater...\n\nAt any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters.\n\nYou'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, {name}!", sourceObjective = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.", progress = "Larion's still not speaking to me! He sure knows how to hold a grudge.", completion = "I admit, I'm a bit hesitant to touch that stuff, {name}! But if Gregan says it'll work, then I'm willing to give it a try!", sourceObjectiveStatus = "unverified-source-field" }
quests[4144] = { id = 4144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodpetal Sprouts", progress = "Here's the plan, {name}: Go out and collect some bloodpetal sprouts -- you know, the plants that haven't fully sprouted yet, and bring them here. Then I'll see what the Atal'ai haze can do.\n\nYou may think I'm vengeful... Actually, you'd be right about that! \n\nTruth is, I know the way out of here, but until Larion will admit that I'm right, I'm staying right here!\n\nSo off with you, find those bloodpetal sprouts and let's have some fun!", completion = "Here goes nothing, {name}! This will get Larion's attention!" }
quests[4145] = { id = 4145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Larion and Muigin", description = "See Muigin over there? It's HIS fault we're lost!\n\nI'm the one that knew the way, but he insisted he knew a shortcut, and we ended up here!\n\nTo make matters worse, now he keeps sending his crazy plant pests to annoy me. I'm so angry that I'm not planning on talking to him any time soon, but these pests are too much to handle.\n\nWhy don't we try to limit his supply, first thing. Go out and hunt some Bloodpetals, then return to me.", sourceObjective = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.", completion = "Thanks for your help, {name}, but I'm afraid I have some bad news...", sourceObjectiveStatus = "unverified-source-field" }
quests[4146] = { id = 4146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zapper Fuel", description = "You're in luck, {name}! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests.\n\nI can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.", sourceObjective = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.", progress = "This is exhausting, {name}. Those things just won't leave me alone!", completion = "So, Marvon wasn't around? Well, show me what you got, anyway.", sourceObjectiveStatus = "unverified-source-field" }
quests[4147] = { id = 4147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marvon's Workshop", description = "I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!\n\nI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!\n\nWe'll need the help of my friend, Marvon, who has a workshop in Ratchet.  I'm sure he'll be able to create some sort of gadget that will help us.", sourceObjective = "Travel to Marvon Rivetseeker's workshop in Ratchet.", completion = "Marvon's been gone quite a long time now, {name}. He went off to Tanaris to study some of the ancient troll ruins.\n\nNow, what was it that you said you needed?", sourceObjectiveStatus = "unverified-source-field" }
quests[4148] = { id = 4148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodpetal Zapper", progress = "For the zapper to work, it needs a sample of the target creature. Head out into the crater and collect a Bloodpetal sprout. Then I can calibrate it to work on Muigin's little friends...\n\nIf he weren't so stubborn, we could be on our way home, already... But until then, I'll just have to show him that his little prank doesn't bother me at all!", completion = "Looks like this is going to work perfectly, {name}. Now remember, if you see any of those pests around, don't hesitate to use that zapper!" }
quests[4161] = { id = 4161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recipe of the Kaldorei", description = "Long ago, the night elves were called the kaldorei, a name that means \"children of the stars.\" Learning of the past is an important step in your path as a {class}, {name}, so listen well to what I have to tell you.\n\nThe kaldorei have always taken much pride in their harmonious relationship with nature. This means that we only take from nature what is necessary, and that we return in kind. This balance has afforded us much, {name}.\n\nGo out and collect seven small spider legs -- no more than that, and return to me.", sourceObjective = "Collect 7 Small Spider Legs for Zarrin in Dolanaar.", progress = "Remember the balance, {name}. I wish you to develop an understanding and a strong empathy for the living forests.", completion = "Always remember what I have shown you today, {name}. You are part of the balance that the night elves strive to keep intact, even during troublesome times.", sourceObjectiveStatus = "unverified-source-field" }
quests[4181] = { id = 4181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblin Engineering", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n{name}, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", sourceObjective = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well {name}, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked {name}, and you might learn something.", sourceObjectiveStatus = "unverified-source-field" }
quests[4182] = { id = 4182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonkin Menace", description = "Life in the Burning Steppes is rife with conflict.\n\nJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.\n\nEnough lamenting! We have a problem, {name}. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.", sourceObjective = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake.", progress = "How goes the dragon hunt?", completion = "Superb slaying, {name}. Now that we know you can handle yourself around dragonkin, we can talk of more pressing matters.", sourceObjectiveStatus = "unverified-source-field" }
quests[4183] = { id = 4183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Masters", description = "We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.\n\nIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.\n\nTake this letter to Magistrate Solomon. He will know what must be done.\n\n<Helendis hands you a sealed letter.>", sourceObjective = "Travel to Lakeshire in Redridge Mountains and deliver Helendis Riverhorn's Letter to Magistrate Solomon.", progress = "Greetings, {name}. Have we met before? You look vaguely familiar.", completion = "<Magistrate Solomon opens the sealed letter from Helendis and begins reading.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4184] = { id = 4184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Masters", description = "This is grim news, {name}. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?\n\nYou must take this information to King Varian Wrynn in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost.", sourceObjective = "Travel to Stormwind and deliver Solomon's Plea to King Varian Wrynn.\n\nKing Varian Wrynn resides in Stormwind Keep.", progress = "What brings you to Stormwind Keep?", completion = "Dragons? Impossible!", sourceObjectiveStatus = "unverified-source-field" }
quests[4185] = { id = 4185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Masters", description = "Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.\n\nSpeak with Lady Prestor, {name}. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation.", sourceObjective = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.", progress = "<Bolvar watches you intently.>", completion = "<Bolvar cups his chin as if in deep thought.>\n\nWhile I respect Lady Prestor's stance, I believe that there is a solution to this dilemma that may put all of our concerns to rest.", sourceObjectiveStatus = "unverified-source-field" }
quests[4186] = { id = 4186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Masters", description = "I am going to empower you as an acting deputy of Stormwind, {name}.\n\nReturn to Magistrate Solomon in Lakeshire and deliver this decree.", sourceObjective = "Take Wrynn's Decree to Magistrate Solomon in Lakeshire.", progress = "Any news from Bolvar?", completion = "It could have been worse, I suppose...\n\n<Magistrate Solomon looks you over.>\n\nIt appears as if the fate of Lakeshire rests squarely on your shoulders.\n\n<You notice Magistrate Solomon blinking rapidly. He appears to be crying.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4201] = { id = 4201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Love Potion", description = "Oh, the pains of love!  My dear Private Rocknot is immune to my charms.  I am spurned!  It's maddening!\n\nYou must help me!  We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart.  To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un'Goro.  You can place the water in this vial.\n\nPlease, {name}, help a poor soul in her quest for happiness!", sourceObjective = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.", progress = "Do you have the ingredients?  The hole in my heart threatens to consume me!", completion = "Oh, you've done it!  I can now make my potion and use it on Rocknot.  Finally, he will fall victim to my charms!\n\nThank you, {name}.  You are a champion of love!", sourceObjectiveStatus = "unverified-source-field" }
quests[4221] = { id = 4221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4222] = { id = 4222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4223] = { id = 4223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Masters", description = "<Magistrate Solomon sighs.>\n\nYou must return to the Burning Steppes, {name}. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.", sourceObjective = "Speak with Marshal Maxwell in the Burning Steppes.", completion = "<Marshal Maxwell laughs.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4224] = { id = 4224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The True Masters", description = "What? You thought you were the first? How many soldiers must we lose before Stormwind acts?\n\nWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.\n\nWhat we need is that documentation. Speak with Ragged John, {name}. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.", sourceObjective = "Speak with Ragged John.", progress = "Have you spoken with John yet?", completion = "I could have warned you, but what fun is that?", sourceObjectiveStatus = "unverified-source-field" }
quests[4241] = { id = 4241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshal Windsor", description = "So that good for nothing coward says that Windsor is alive, eh?\n\nSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.\n\n<Maxwell laughs.>\n\nI bet you are getting tired of hearing that, aren't you?", sourceObjective = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\n\nYou recall Ragged John talking about Windsor being dragged off to a prison.", completion = "Where is he! I'll murder him!", sourceObjectiveStatus = "unverified-source-field" }
quests[4242] = { id = 4242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned Hope", description = "Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.\n\nHe is a blind buffoon. Proof stands two feet away from him and he does not see.\n\nAs for my data, it's lost. Gone. Unrecoverable.\n\nShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.\n\nLeave me, {name}.", sourceObjective = "Give Marshal Maxwell at Morgan's Vigil in the Burning Steppes the bad news.", completion = "He's gone mad, apparently.\n\n<Maxwell lowers his head in mourning.>\n\nIt is unfortunate that a once proud and noble warrior would be turned into a blithering head case. I GUESS we've reached a dead end...\n\nI must reward you for your efforts thus far, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4243] = { id = 4243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Unfortunately, something's happened to one of my greatest inventions. You've seen mechanical squirrels, yes? Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has scrying gems for eyes so I could see everything she saw. She made it to Fungal Rock--the apes' lair--just east of here, and that's when I lost contact. The last thing I saw was one of their alpha males rushing up to say hello to her!\n\nCan you help me find her?", sourceObjective = "Find A-Me 01 in Un'Goro Crater.", completion = "As you look A-Me 01 over, you see two huge dents tarnishing what Karna obviously feels is a well-crafted piece of engineering. One dent decorates A-Me 01's shoulder, the other is on her head.\n\nNo power seems to be running through her components as you investigate further.", sourceObjectiveStatus = "unverified-source-field" }
quests[4244] = { id = 4244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "A little further investigation shows a panel that slides open. Clearly written above some wiring is the statement, \"Replace Mithril Casing And Turn Power Off Then On.\"\n\nTaking a moment to replace the panel, you wonder if it'll be that simple to fix A-Me 01 and get her back to Karna Remtravel near Marshall's Refuge.\n\nOnly trying it will tell.", sourceObjective = "Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.", progress = "The panel in which the mithril casing goes is still closed shut. The rest of A-Me 01 remains inert.", completion = "You remove the panel from A-Me 01's back yet again and carefully remove the old mithril casing that seems to have burnt out. The new one slides into place easily. The only thing left to do, assuming the mithril casing was the problem, is to flip the switch to the \"Off\" position, and then back to the \"On\" position.", sourceObjectiveStatus = "unverified-source-field" }
quests[4245] = { id = 4245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Checking to see if you're prepared to lead A-Me 01 back to Karna Remtravel, you flip the switch to the \"Off\" position. Glancing around once again to make sure none of the gorillas are coming, you prepare to see what happens when you flip the switch back to the \"On\" position.\n\nThis is your last chance... are you sure this is what you want to do?", sourceObjective = "Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.", progress = "Have you been able to help A-Me? That mithril casing you mentioned being destroyed was a good guess at what was wrong. I'm sure if you replace that, she'll reactivate and be able to come home.", completion = "Oh, you've done it! Wonderful! Thank you, {name}.\n\nOh, my poor, A-Me. Look at all those dents. We'll get her up and running perfectly with just a little work.\n\nThank you again, {name}. I really appreciate it.", sourceObjectiveStatus = "unverified-source-field" }
quests[4261] = { id = 4261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Spirit", description = "Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos...\n\nThe skull of Gul'dan ensured that none were spared here. All fell to the corruption.\n\nEven now, as a spirit, I still find myself trapped, bearing the suffering of this land. Help me find my way home. Please, {name}, tell me you will lead an ancient spirit away from here, where I may finally rest.\n\nOnce I am free, seek out Kayneth Stillwind, a druid that resides in Forest Song, to the east.", sourceObjective = "Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.", completion = "Yes, {name}. Felwood has been through much hardship. Thank you for what you have done.\n\nOne day, we may be able to reclaim Felwood from the corruption; every kind deed helps.", sourceObjectiveStatus = "unverified-source-field" }
quests[4262] = { id = 4262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overmaster Pyron", description = "The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse.\n\n<Jalinda picks up some ashes from the ground and releases them into the air.>\n\nOne nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths!\n\nHe guards the entrance at the Blackrock Quarry.", sourceObjective = "Slay Overmaster Pyron.\n\nYou recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?", progress = "<Jalinda appears to be staring at your head.>", completion = "Incendius? Oh dear...", sourceObjectiveStatus = "unverified-source-field" }
quests[4263] = { id = 4263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incendius!", description = "Are you sure Pyron said 'Incendius' when he died?\n\n<Jalinda swallows hard.>\n\nLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?\n\nDo you think you can handle another mission? I don't have anybody else to send, {name}!\n\nWe will never get a team in if Incendius continues to raise Pyron from the ashes.\n\nYou'll have to find and destroy Lord Incendius!", sourceObjective = "Find Lord Incendius in Blackrock Depths and destroy him!", completion = "Oh dear! Are you sure Incendius said 'Ragnaros?'\n\n<Jalinda hands you something and pats you on the wrist as she fades deep into thought.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4264] = { id = 4264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Crumpled Up Note", description = "The note has stains covering its surface. The text is barely legible, but you make out the following:\n\n...sweet irony...\n\n...the fall of the broken Alliance...\n\n...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...\n\n...Argelmach is almost done with the decryption of Windsor's notes.\n\nOur lord will rise from the depths and crush any that remain...\n\n-Emperor Dagran Thaurissan.", sourceObjective = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.", progress = "<Marshal Windsor eyes the note in your hand.>\n\nWhat do you have there, {name}?", completion = "<Marshal Windsor takes the note and begins reading.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4265] = { id = 4265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freed from the Hive", description = "The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.\n\n\"Thank Elune - you've saved me, friend!  I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me.  Were you sent by the Stronghold?\"\n\nIt would seem that you've found the missing courier!", sourceObjective = "Free Raschal from the Zukk'ash hive.\n\nReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.", completion = "Welcome home, {name}.  Raschal checked in just a little while ago and told me what happened.\n\nI... no, the entire Stronghold can't even begin to thank you for your great deed; Raschal would have been dead without your timely aid, and your assistance came to us without even so much as the whisper of a mercenary's fee.  You bear the mark of a true hero.  Know that you will always have a friend in Ginro Hearthkindle.", sourceObjectiveStatus = "unverified-source-field" }
quests[4266] = { id = 4266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Welcome", description = "{name}, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.\n\nGeneral Feathermoon is waiting for you in the main compound.", sourceObjective = "Speak with Shandris Feathermoon in Feathermoon Stronghold.", completion = "{name}, I give you my warmest thanks for the aid you've given us.  Your bravery in the face of overwhelming odds has warranted a reward worth a thousand times greater.  Nevertheless, I hope you accept this on behalf of the entire Stronghold.\n\nNow, if I may... I'd like to ask for your aid one more time.  In light of the discovery of the Zukk'ash hive here in Feralas, I think you're the best choice for this mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[4267] = { id = 4267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of the Silithid", description = "I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.\n\nYou're dismissed - good luck, {name}; may Elune watch over us all.", sourceObjective = "Bring Raschal's Report to Gracina Spiritmight in Darnassus.", progress = "Welcome to this blessed temple, friend.  Your arrival here from Feathermoon Stronghold has been foretold to me.  Do you have the report Shandris Feathermoon asked you to bring?", completion = "We night elves know of the terror outlined in this report.  Shandris was wise to send this, and you, to me.\n\nThese creatures will consume Feralas rapidly; they are nothing short of one of the greatest menaces we all will ever face.  The insects you and the courier encountered are known as the silithid.  They are mere tools of one of the greatest threats that both the Horde and Alliance will ever face.\n\nI pray we will have the resolve to defeat them before they destroy us.", sourceObjectiveStatus = "unverified-source-field" }
quests[4281] = { id = 4281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thalanaar Delivery", description = "This parcel of goods you found in the Woodpaw gnoll camps was supposed to be delivered to the small way-station of Thalanaar in southeastern Feralas.  Regardless of the missing courier's fate, the task of delivering the parcel remains unfinished.\n\nExamining the parcel in detail reveals a hand written name of \"Falfindel Waywarder\" on the outside of the packaging.  Perhaps this is the parcel's ultimate recipient.", sourceObjective = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.", progress = "Welcome to Thalanaar, {class}.  Do you need assistance of some sort?", completion = "Elune be praised, the delivery from Feathermoon Stronghold has finally arrived!\n\nYour presence here indicates to me that perhaps some ill fate may have befallen Raschal, our usual courier.  I hope that everything works out.  I know that recently, the Woodpaw have become highly agitated from some source to their south.  Maybe he fell to the wilds there; I would be careful, friend.\n\nRegardless, thank you again.  Here is payment for this parcel's delivery.", sourceObjectiveStatus = "unverified-source-field" }
quests[4282] = { id = 4282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shred of Hope", description = "<Marshal Windsor shakes the note excitedly.>\n\nDo you realize what this means, {name}?\n\nPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.\n\nI hope you are ready to battle.\n\nVenture forth and find these two villains! Destroy them and return my lost information.", sourceObjective = "Return Marshal Windsor's Lost Information.\n\nMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.", progress = "Soon this grand subterfuge will be over.", completion = "<Marshal Windsor snatches the two tablets from your hands.>\n\nWe need to get out of here!", sourceObjectiveStatus = "unverified-source-field" }
quests[4283] = { id = 4283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FIFTY! YEP!", description = "I'm going to let you in on a little secret, soldier. Come a little closer.\n\nI'M THE ONLY SANE ONE HERE!\n\nLook at these people! Would you believe that they're all insane!? Well they are! NUTS! CRAZY!\n\n<Oralius lowers his voice.>\n\nLet's just keep that between me, you, and my pal Captain Winky.\n\n<Oralius grabs at the air and squeezes.>\n\nAnyhooooo... I'm collecting badges to go along with my ogre ear collection. Orc is the flavor of the day. Fifty. GO!\n\n<Oralius blows into a horn.>\n\nSHIP IT!", sourceObjective = "Collect 50 Blackrock Medallions.", progress = "<Oralius is talking into a rather large, severed ogre ear.>\n\nBurning Steppes to control, come in control.", completion = "You've done it! Your reward is: RUB MY BELLY! GO ON! RUB IT!", sourceObjectiveStatus = "unverified-source-field" }
quests[4284] = { id = 4284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals of Power", description = "I'm sure you've noticed 'em, {name}. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I've been doing experiments here with them for a while, but I can't seem to find anything. Well, I haven't yet, anyway.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?", sourceObjective = "Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.", progress = "I just know I'm onto something here, {name}!", completion = "Now I will continue my experiments! Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4285] = { id = 4285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Northern Pylon", description = "What could they be for? I can't get the thought out of my head!\n\nIt's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me.\n\nAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, {name}. I just know they exist.", sourceObjective = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", progress = "Have you visited the pylon, {name}?", completion = "I know the stories are true, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4286] = { id = 4286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Stuff", description = "Captain Winky tells me that the Dark Irons in the Depths got all the good stuff. Ain't that right, Winky?\n\n<Oralius does his best impersonation of a pirate.>\n\nARRR MATEY! IT BE RIGHT!\n\nSee what I'm saying? You need to get in there and bring me back some samples of the good stuff.\n\nGet in there and shake your moneymaker!", sourceObjective = "Collect 20 Dark Iron Fanny Packs.", progress = "I can't be bothered right now, {name}. Me and Winky got a meeting to attend.", completion = "<Oralius starts rummaging through the mountainous pile of fanny packs.>\n\nOH WONDERFUL!\n\n<Oralius sticks his large nose into the pile and takes a whiff.>\n\nDELICIOUS! Look at all these goodies!\n\nTake one for yourself, {name}. There's plenty to go around.", sourceObjectiveStatus = "unverified-source-field" }
quests[4287] = { id = 4287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Pylon", description = "During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, {name}. I guess that they are quite large, with crystals lining their interiors.\n\nAlthough I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found\n\nSo why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?", sourceObjective = "Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.", progress = "Have you visited the pylon, {name}?", completion = "Un'Goro is such a strange place, {name}. When you enter the crater, it's as if you are in a completely different world...", sourceObjectiveStatus = "unverified-source-field" }
quests[4288] = { id = 4288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Western Pylon", description = "My experiments so far have not yielded any positive results, {name}. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist.\n\nPerhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first!\n\n{name}, search the western area of the crater; a pylon is said to be somewhere in that area.", sourceObjective = "Discover the location of the Western Crystal Pylon.", progress = "Have you visited the pylon, {name}?", completion = "There are many hidden areas of the crater along the sides. Try exploring the winding paths if you can't think of anywhere else to look, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4289] = { id = 4289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apes of Un'Goro", description = "This crater has many strange creatures--they seem to be nobler versions of the creatures found throughout my homeland and beyond. I cannot explain it, but this place cries of the Earth Mother. I pay homage to her every time I track one of her beautiful creatures across its basin.\n\nIf you too wish to feel the enlightenment that accompanies such a great feat, then head to the north. There you'll find great apes who are a test for any mortal's strength. Bring me their pelts... prove your strength.", sourceObjective = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.", progress = "Have the creatures here bested you already, {name}?\n\nDo not be dissuaded so easily. Tracking and defeating the apes of Un'Goro is no simple task, even for a great hunter.", completion = "So, you have proven strong, strong enough to best the great apes of Un'Goro--that is good. The challenge was small compared to Lar'korwi, but I will not take such a great victory away from you.\n\nThese pelts will make wonderful clothing for my tribe. You have helped me and proven worthy.\n\nBefore you set off on another task, let us give praise to the Earth Mother and thank the spirits of those apes you killed--they must know their deaths will not be wasted.", sourceObjectiveStatus = "unverified-source-field" }
quests[4290] = { id = 4290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fare of Lar'korwi", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nReturn to me afterwards.", sourceObjective = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.", progress = "Do not take my words lightly, {name}. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar'korwi and defeat him.", completion = "This will do nicely, {name}. It seems Lar'korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.\n\nRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you've angered Lar'korwi enough that he will not kill me until after he's tasted your flesh.", sourceObjectiveStatus = "unverified-source-field" }
quests[4291] = { id = 4291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scent of Lar'korwi", description = "I'm actually surprised he has not come for you yet, {name}. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", sourceObjective = "Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.", progress = "Be careful, {name}. Getting close to any of nest of eggs surely will provoke the mothers... even if you've already secured a gland from one. The mothers can be just as deadly as Lar'korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar'korwi out from hiding.", completion = "Ah, fine specimens, {name}. The two pieces you've found should be perfect for baiting Lar'korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death.", sourceObjectiveStatus = "unverified-source-field" }
quests[4292] = { id = 4292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bait for Lar'korwi", description = "This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", sourceObjective = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", progress = "Do not let fear overpower you, {name}. Fear is the great betrayer... you must remain strong!\n\nTake the meat, place it in the small valley, and then use the gland on it. Only then will death come for you.", completion = "The Earth Mother be praised! You've done it! Fair play to you, {name}. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.\n\nOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations.", sourceObjectiveStatus = "unverified-source-field" }
quests[4293] = { id = 4293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sample of Slime...", description = "Felwood is a forest far north of the Barrens, even farther than Ashenvale. There, slimes are found all around pools of water blessed by the touch of Fel. The Scourge decimated the area with attacks of Infernals and other demonic magics--the slimes supposedly crept up through the earth during these attacks.\n\nGather samples of Felwood slimes and we will use the testing equipment next to me to create a control group for our tests against other samples you gather.", sourceObjective = "Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely.", progress = "I will need at least five corrupted samples for our control group, {name}. Continue to gather Felwood slime samples until you're able to give me that which we'll need. The Lady Sylvanas decrees it...", completion = "Ah, excellent. These samples will do nicely. I thank you for your help.\n\nOnce we've gathered all the samples of slimes, we'll be able to determine more. I am beginning to suspect that Lady Sylvanas' hunch was not only correct, but more insightful than even she could have predicted. These samples are very interesting. Just seeing how they've reacted with my compounds... hmm, yes, we'll definitely need to investigate further.", sourceObjectiveStatus = "unverified-source-field" }
quests[4294] = { id = 4294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... and a Batch of Ooze", description = "Have you heard of the Un'Goro Crater, {name}? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life.\n\nIt is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets.\n\nI would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.", sourceObjective = "Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely.", progress = "Yes, {name}? How goes your search?", completion = "Truly amazing, {name}. This Un'Goro Crater is holding many more secrets than I expected. I wonder what else we will discover as we test further.\n\nSimply amazing... look at the purity of these samples. Hmm, I wonder what it could mean. They seem to be elemental in nature, but... something more. They remind me of... of the Old Gods. We've found traces of them throughout Azeroth, and now I wonder if these creatures aren't related to them somehow.\n\nWe shall have to test further.", sourceObjectiveStatus = "unverified-source-field" }
quests[4295] = { id = 4295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocknot's Ale", progress = "Oh, ale!  I would kill for some Dark Iron ale!!  Quick, I'm getting sober!  I know this because sobriety blurs my vision... and it's making you look like the {race} I slew last week!", completion = "What's this?  Ah!  It smells like Dark Iron Ale!  Drink has blurred my sight, but I can tell that you, sir, are a real friend!" }
quests[4296] = { id = 4296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tablet of the Seven", description = "I came to the Burning Steppes, following the legends of the Seven.  They were dwarves of great knowledge and power, and if you have knowledge and power, then wealth is sure to follow.\n\nThat's what I want.  Wealth!\n\nIf we can learn more of the Seven, then maybe we can get rich together.  The ruins of Thaurissan is rumored to keep the Tablet of the Seven, which holds knowledge of the ancient dwarves.  Find this tablet, copy its text and bring it to me.  Let's discover its secrets together!", sourceObjective = "Collect the Tablet Transcript.", progress = "Do you have the writings of the Seven, {name}?  Have you learned the secrets from their tablet?", completion = "Ah, you found the tablet!  And your transcription is superb!  Are you sure you're a {class} and not a scribe?\n\nHere you are, {name}.  Here is the payment I promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[4297] = { id = 4297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Food for Baby", description = "Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know.\n\nI'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatched.", sourceObjective = "Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands.", progress = "Find that meat yet, {name}? Your little egg here's just about ready to hatch. If he don't have a good enough first meal, then he might not make it past his first week, and I'd hate for that to happen.\n\nCan't much lie to ya, {name}. I'm jealous of you gettin' this egg to begin with. Don't make me regret helpin' ya out like this.", completion = "These'll do nicely, and if I'm not mistaken, your little egg's just about ready to hatch. How does it feel? You know, you about to be a father? Haha, didn't think ya'd have to deal with such responsibility, now did ya?", sourceObjectiveStatus = "unverified-source-field" }
quests[4298] = { id = 4298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becoming a Parent", description = "Whoa, it was a lot more ready than I thought...", sourceObjective = "Speak to Agnar Beastamer in the Hinterlands.", completion = "Here, take the egg... better you have it so it bonds to you and looks to you to be its dadda.\n\nCongrats, {name}. You're a parent... kinda.", sourceObjectiveStatus = "unverified-source-field" }
quests[4300] = { id = 4300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bone-Bladed Weapons", description = "Hmm, maybe there be somethin' you can do for the Hand now that me think 'bout it. Yes, Jes'rimon could use your help for sure.\n\nIn Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death. The Hand have... clients... that like weapons crafted from these claws. Bring me many of those white claws, and me pay you good coin. Do it fast enough, and maybe me help you in other ways.", sourceObjective = "Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.", progress = "Me clients are not so patient, {name}. Have you gotten any of the claws yet?", completion = "Ah, these do nicely. Thank you, {name}. An' you be here long before they needed... that be good.\n\nMaybe we have a weapon fashioned for you from the claws. What do you say?", sourceObjectiveStatus = "unverified-source-field" }
quests[4301] = { id = 4301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mighty U'cha", description = "While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task.\n\nI call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunter.", sourceObjective = "Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.", progress = "U'cha... the beast was magnificent. Huge and red, with teeth the size of daggers. His arms as thick as tree trunks, and as fast as any mountain lion I have ever laid eyes upon. You should consider yourself lucky to find such a test of bravery--my people would go generations without seeing such a creature.", completion = "Well done, {name}. I am pleased. You have done a great thing here today.\n\nU'cha was one of the greatest apes I had ever seen. The fact that you have bested his strength speaks well of your own strength... and courage.\n\nIt is only fitting that I give you this as a sign of respect. You have earned it.", sourceObjectiveStatus = "unverified-source-field" }
quests[4321] = { id = 4321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Sense of It", description = "The information you have given me about the pylons is very interesting...\n\nGive me a moment to do some calculations, {name}. Speak to me again in a moment and I should be able to give you the answer we have been looking for.", sourceObjective = "Speak with J.D. Collie in a moment.", completion = "Alright, {name}. This is fascinating... I can only hope that my diagrams are correct! I compiled everything into this manual, which you can have.\n\nI believe I can answer any questions you have about the crystals now, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4322] = { id = 4322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jail Break!", description = "We need to get out of here, {name}. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.", sourceObjective = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.", progress = "You look exhausted, {name}. Perhaps you should have a seat by the fire and relax.", completion = "Amazing, {name}. Simply amazing. Windsor stormed through here not five minutes ago. He makes some grand claims but purports that they are supported by his evidence. He is on his way to Stormwind now to confront Bolvar and ... Lady Prestor.", sourceObjectiveStatus = "unverified-source-field" }
quests[4324] = { id = 4324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yuka Screwspigot", description = "Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth.\n\nMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes.  She sent word to me, asking for some hired hands.\n\nSo, what do you say?  Want to help?  If so, then speak with my sister.  You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock.", sourceObjective = "Speak with Yuka Screwspigot in the Burning Steppes.", completion = "Yes, I'm looking for my brother.  We must find him and retrieve him, bless his heart.\n\nBut if we can't bring all of him... then his head will suffice.", sourceObjectiveStatus = "unverified-source-field" }
quests[4341] = { id = 4341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kharan Mighthammer", description = "You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!\n\n<The King sobs.>\n\nAnd now she's gone, {name}!\n\nI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!\n\nKharan is supposedly being held prisoner there... find him! I want answers!", sourceObjective = "Travel to Blackrock Depths and find Kharan Mighthammer.\n\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.", completion = "Please, let me explain.", sourceObjectiveStatus = "unverified-source-field" }
quests[4342] = { id = 4342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kharan's Tale", description = "Please, hear me out before passing judgement!", sourceObjective = "Listen as Kharan Mighthammer tells his story.", progress = "Allow me to finish telling my story.", completion = "As you can see, there was nothing I could have done.", sourceObjectiveStatus = "unverified-source-field" }
quests[4343] = { id = 4343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4361] = { id = 4361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bearer of Bad News", description = "You must take this information back to King Magni, {name}. He will know what to do!", sourceObjective = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.", completion = "<King Magni slams his fist down in anger.>", sourceObjectiveStatus = "unverified-source-field" }
quests[4362] = { id = 4362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Kingdom", description = "It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.\n\nYou may be my last hope, {name}. You must rescue my dear daughter, Moira!\n\nThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.\n\nAnd {name}, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!", sourceObjective = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", completion = "<Princess Bronzebeard weeps over the loss of Emperor Dagran Thaurissan.>\n\nWhy???", sourceObjectiveStatus = "unverified-source-field" }
quests[4363] = { id = 4363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Princess's Surprise", description = "Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!\n\n<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>\n\nReturn to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.\n\nWhether he approves or not, it shall be.", sourceObjective = "Return to Ironforge and speak with King Magni Bronzebeard.", completion = "<King Magni Bronzebeard is visibly upset.>\n\nIt seems that even in death, Thaurissan has won.\n\nYou are dismissed, {name}. Before you leave, you may choose your reward from the royal vault.", sourceObjectiveStatus = "unverified-source-field" }
quests[4381] = { id = 4381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Restore", progress = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[4382] = { id = 4382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Force", progress = "The Pylon table allows you to combine green power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to increase your spirit.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[4383] = { id = 4383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Ward", progress = "The Pylon table allows you to combine green power crystals with red power crystals.\n\nAccording to J.D.'s manual, this combination can be used to strengthen the protection you have against physical damage.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[4384] = { id = 4384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Yield", progress = "The Pylon table allows you to combine red power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to weaken an enemy's defenses.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[4385] = { id = 4385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Charge", progress = "The Pylon table allows you to combine red power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a large explosion that can inflict damage on your enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[4386] = { id = 4386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Spire", progress = "The Pylon table allows you to combine blue power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a shield that does damage to enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours." }
quests[4401] = { id = 4401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4402] = { id = 4402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgar's Cactus Apple Surprise", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, {name}. If you bring me 6 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", sourceObjective = "Bring Galgar 6 Cactus Apples. You remember him saying that they could be found near cactuses.", progress = "Have you finished collecting cactus apples?", completion = "Wonderful, {name}! As promised, here is your cactus apple surprise plus a little something extra.", sourceObjectiveStatus = "unverified-source-field" }
quests[4403] = { id = 4403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4421] = { id = 4421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corruption of the Jadefire", description = "Not many seek adventure here... Felwood's corruption is widespread and indiscriminate.\n\nAs part of the Emerald Circle, I seek to heal this land, but there are some that wish it to fester.\n\nThe ones I speak of are the Jadefire satyrs that dwell to the northwest of here, at the Ruins of Constellas. Led by a particularly cruel satyr named Xavathras, they continue to spread the disease to any creatures they encounter.\n\nWe must defend this land that was once ours. Defeat Xavathras and destroy his minions.", sourceObjective = "Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed.", progress = "The corruption here drives the creatures into madness...", completion = "Ridding Felwood of Xavathras is only the first step in a long process. It will take much work to repair the damage that has been done here.\n\nI sense that there is something much larger than just the satyrs at work here, but we will only know the truth with time...", sourceObjectiveStatus = "unverified-source-field" }
quests[4441] = { id = 4441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felbound Ancients", description = "The flute you found was carved from an ancient protector, the treant allies that have faithfully protected the night elves.\n\nThe satyrs have been able to corrupt anything they come in contact with, which includes the ancients that made Felwood their home. By the use of the fel, the spirit of the ancient has been bound and tortured, never completely released. The felbind you found is no doubt related.\n\nWe must try to purify the flute, {name}. Bring me blessed water from the Temple of the Moon in Darnassus.", sourceObjective = "Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial.", progress = "The water will hopefully release the spirit of the ancient, and allow it to be at peace.", completion = "Thank you, {name}. Now, we must pray that we can undo the damage that has been done...", sourceObjectiveStatus = "unverified-source-field" }
quests[4442] = { id = 4442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purified!", description = "Using the water of Elune, I will attempt to purify the flute. We must end this suffering...\n\nMay Elune guide my hands and heart.\n\nSpeak with me again in a moment.", sourceObjective = "Speak to Eridan again in a moment.", completion = "With the blessed water, I was able to break the link between the flute and the ancient spirit. I do believe though, that if you were to use this flute in a sacred spot, you may be able to summon the ancient spirits.\n\nPerhaps you might try the ruins in the southern part of Irontree Woods. Many corrupted treants inhabited this area at one time, and it is possible that they may still reside there, even in spirit form.", sourceObjectiveStatus = "unverified-source-field" }
quests[4443] = { id = 4443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Whipper Root", progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4444] = { id = 4444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Whipper Root", progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4445] = { id = 4445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Whipper Root", progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4446] = { id = 4446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Whipper Root", progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4447] = { id = 4447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Night Dragon", progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant.  The fruits that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4448] = { id = 4448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Night Dragon", progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant.  The fruits that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4449] = { id = 4449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught!", description = "Hey! Hey, you! Get over here!\n\nYa gotta help me out. I was runnin' from them Dark Iron dwarves, and I hid in here to get out of sight. Damn geologists and their magic ways! They musta seen me hide, cause next thing I knew, they locked the door and stuck me in here.\n\nTeach them geologists a lesson! Oh... an' can ya get me some pieces of silk cloth for... for... nothin'.", sourceObjective = "Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge.", progress = "I ain't got all day! Get me those pieces of silk cloth! I mean geologists. Get those geologists! They deserve to feel my, well... your wrath.", completion = "Oh, this is great! Nice feel to it too!\n\nWhat? Oh, yeah... geologists. Got 'em good, did ya? I can't thank ya enough, {name}. That'll give me some time to finish up in here... Thanks again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4450] = { id = 4450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ledger from Tanaris", description = "Oh, you know what? That reminds me.\n\nYou wanna finish up a little job I took up while I was in Tanaris? It's easy...\n\nKrinkle Goodsteel in Gadgetzan was lookin' for some stuff found here in Searing Gorge and a few other places. Maybe you could take a look at the list and then bring it all to him?\n\nI'll just slide his ledger under the door if you're interested. Take that, and the stuff he wants back to him after ya collected it all.", sourceObjective = "Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris.", progress = "Yes, yes? What can I do for you, {race}? I'm awfully busy and have many patrons requesting my services. Perhaps you can speed things up. I don't mean to be rude, but I just don't have the time if I'm to catch up on all my work.", completion = "Oh, you've seen fit to do some of the work I requested. Excellent. And here I thought you were going to ask me to craft you something.\n\nThese are all perfect... and everything's here. Thank you, {class}.\n\nMaybe it wouldn't hurt to reward you some... hmm, what would you find useful.", sourceObjectiveStatus = "unverified-source-field" }
quests[4451] = { id = 4451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Key to Freedom", description = "The small brass key looks simple enough.. The only thing that seems to make it stand out are some words scratched into the head of it:\n\n\"Dark Iron Outhouse - Do Not Duplicate.\"\n\nYou have no idea what it means or what it will lead to.", sourceObjective = "Search Searing Gorge and find a use for the Grimesilt Outhouse Key you have found.", progress = "*cough*\n\nWho is it? Can't ya see I'm busy?", completion = "Well, I'll be! How in tarnation!? You found the key! I knew them blasted Dark Irons were hiding it after they locked me in here! Thank ya so much, {name}. You're the greatest! Now, just turn the key and let ol' Locheed outta here!", sourceObjectiveStatus = "unverified-source-field" }
quests[4461] = { id = 4461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Whipper Root", progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4462] = { id = 4462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Night Dragon", progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant.  The fruits that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4463] = { id = 4463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Rumination", progress = "Present the components, mortal.\n\nI will also require payment in the form of thirty gold pieces for this creation.", completion = "Take your trinket, fool. Leave me to my studies!" }
quests[4464] = { id = 4464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4465] = { id = 4465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Songflower", progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4466] = { id = 4466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4467] = { id = 4467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Windblossom", progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant." }
quests[4481] = { id = 4481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Constitution", progress = "There is a price to pay for all things in this world. The price for the specific item that you seek is thirty gold pieces.\n\nNaturally, I shall retain the majority of the components which you collected. But worry not, you shall have your trinket.", completion = "It is disgrace to his memory... a mortal, such as yourself, finishing his life's work.\n\nTake your amalgamation and be gone!" }
quests[4482] = { id = 4482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Tenacity", progress = "Thirty gold, {race}. Thirty gold and the required components.", completion = "It took Kariel what would amount to several of your lifetimes to complete the libram that you now hold, {race}. All for what? So that his disciple could stand in the Burning Steppes and bastardize his research in order to satiate a never ending arcane craving... Curse this foul addiction.\n\nI am disgusted with your lack of compassion and insatiable greed. Be gone!" }
quests[4483] = { id = 4483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Resilience", progress = "If it is resilience you desire, thirty gold I require.", completion = "Other librams are lost in this world. Lost in places you would not dare enter. Places you would pray did not exist.\n\nI will drink in the energies of these components. You shall be given the residual waste..." }
quests[4484] = { id = 4484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Libram of Voracity", progress = "Do not waste my time, {race}. Give me what I require. Thirty gold and the components.", completion = "My head throbs... The energies of the vast expanses that makes up our universe... ARGGH!\n\n<Mathredis looks pained.>\n\nTake what you desire and leave!" }
quests[4485] = { id = 4485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Nobility", description = "Hello, {name}. I see your dedication remains strong, as does your faith.\n\nI think it is time you spoke with Duthorian Rall in Stormwind. There are some more lessons for you to learn, and I feel you are prepared.\n\nSeek him out in the Cathedral of Light, and {name}, take these lessons seriously. You've attained your status through humility and hard work, do not disappoint us by becoming arrogant.\n\nBe well.", sourceObjective = "Speak to Duthorian Rall in Stormwind.", completion = "Ah, you've returned to the Cathedral, {name}. Good. A lot has happened recently, and I would seek your aid if you prove worthy.\n\nMany treacherous enemies are about. I will need your help to stop them.", sourceObjectiveStatus = "unverified-source-field" }
quests[4486] = { id = 4486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Tome of Nobility", description = "Well, well, well, look at the mighty paladin in all <his/her> regality.\n\nSorry, {name}, I meant no offense... I just get a little jealous sometimes when I see some of the feats you've accomplished. Tiza tells me it's my weakness, and I swore to her I'd work on it. It's just hard sometimes, you know?\n\nBut the reason I wanted to talk to you was because Duthorian Rall in Stormwind sent word for you to meet him in the Cathedral of Light when you're ready. Sounded important. Sounded like something's going on.", sourceObjective = "Speak to Duthorian Rall in Stormwind.", completion = "Ah, you've returned to the Cathedral, {name}. Good. A lot has happened recently, and I would seek your aid if you prove worthy.\n\nMany treacherous enemies are about. I will need your help to stop them.", sourceObjectiveStatus = "unverified-source-field" }
quests[4487] = { id = 4487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summon Felsteed", description = "Ah, good, you're here. I sent a <succubus/infernal> after you to get your attention, but it seems you were able to get here before it found you. No matter.\n\nThere has been some talk lately of your growing power--that is good for you, possibly bad for others. But those are irrelevant points. The point is, I feel you've proven yourself and therefore are deserving of... hehe... a blessing of sorts.\n\nAbove Ratchet in the Barrens you'll find a man named Strahad. I believe you've crossed paths before.", sourceObjective = "Speak to Strahad Farsan in Ratchet.", completion = "So, you've decided to grace my presence again. How kind of you.\n\nMy acolytes wondered if you'd ever show up. I told them there was no doubt. When power is concerned, you are drawn in like a moth to the flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[4488] = { id = 4488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summon Felsteed", description = "Ah, {name}, you've seen fit to grace us with your presence. How wonderful!\n\nI hope you do not expect us to wait on you hand and foot also. You may be growing quickly in power, but you still are a pup when it comes to true knowledge and understanding. If you're not careful, corruption will overwhelm you and your weak will.\n\nBut I should get to the point: Strahad wishes to speak to you. He is still residing in his tower overlooking Ratchet in the Barrens. I suggest not taking too long.", sourceObjective = "Speak to Strahad Farsan in Ratchet.", completion = "So, you've decided to grace my presence again. How kind of you.\n\nMy acolytes wondered if you'd ever show up. I told them there was no doubt. When power is concerned, you are drawn in like a moth to the flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[4489] = { id = 4489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summon Felsteed", description = "You, {race}! Come here!\n\nYou're the one they call {name}, yes?\n\nI thought as much. I will keep this short: you're growing in power, and it has been acknowledged. And now, the time has come that you are rewarded for your efforts.\n\nGo to the Barrens. There, above Ratchet, you'll find Strahad Farsan--perhaps you remember him? He would have words with you. I wouldn't take long.", sourceObjective = "Speak to Strahad Farsan in Ratchet.", completion = "So, you've decided to grace my presence again. How kind of you.\n\nMy acolytes wondered if you'd ever show up. I told them there was no doubt. When power is concerned, you are drawn in like a moth to the flame.", sourceObjectiveStatus = "unverified-source-field" }
quests[4490] = { id = 4490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summon Felsteed", description = "I would give you a reward for your patience and hard work. But know this, the ability to summon a Felsteed will be much more difficult in the future. You will have to earn it... and it will not be easy.\n\nFor now, go with the power to summon such a creature and use it as you see fit.", sourceObjective = "Speak to Strahad Farsan in Ratchet to learn the ability to summon a Felsteed.", completion = "Good luck, {name}. I look forward to seeing you in the future.", sourceObjectiveStatus = "unverified-source-field" }
quests[4491] = { id = 4491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Help From My Friends", description = "Ugh... It's so hot...\n\nI was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion.\n\nPlease, help me get back to my friend Spraggle at Marshal's Refuge. I think I'm well enough to follow you there.\n\nI am feeling a little out of it, so if I do happen to faint again, just splash some water on me from Spraggle's canteen. That should work, I hope...", sourceObjective = "Lead Ringo to Spraggle Frock at Marshal's Refuge.\n\nIf Ringo faints, use Spraggle's Canteen to revive him.", completion = "Ringo's not in the best shape, {name}, but I am glad to have him back in one piece!\n\nThank you for finding him.", sourceObjectiveStatus = "unverified-source-field" }
quests[4492] = { id = 4492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost!", description = "You've got to help me, {name}! My friend, Ringo left earlier to explore the volcano to the south of here, and he has been gone way too long. I am really worried about him.\n\nDo you think you could find him? Why don't you take my canteen with you -- if you do find Ringo, I'm sure he'll need it!", sourceObjective = "Find Ringo at Fire Plume Ridge.", progress = "Wha... What?", completion = "Oh... I'm so glad someone found me...", sourceObjectiveStatus = "unverified-source-field" }
quests[4493] = { id = 4493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Silithid", description = "It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.\n\nWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the silithid.", sourceObjective = "Speak to Alchemist Pestlezugg in Gadgetzan.", completion = "Yes, I gathered that Gracina sent you to me.  Your experience in fighting these beasties is priceless; no one to my knowledge has ever dealt with their kind before.  As for Gracina's idea that Un'Goro Crater is their heart... perhaps it is.  Un'Goro is a mysterious and dangerous jungle to the west of here.  Perhaps it is also one step closer to figuring out what the silithid are all about.", sourceObjectiveStatus = "unverified-source-field" }
quests[4494] = { id = 4494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Silithid", description = "It would seem that the silithid's intent, nay - reason for being, is to devour everything in their path that is not of their ecology.  Their focus is singular, and it is for this reason they are a grave threat to all life on Azeroth.\n\nWhat we've seen to date is but the first stages.  I suspect that their strength comes from deeper in Kalimdor: Un'Goro Crater.  Go to Gadgetzan in the Tanaris desert and speak to Alchemist Pestlezugg.  Tell him of my theory; he will surely aid us in fighting the silithid.", sourceObjective = "Speak to Alchemist Pestlezugg in Gadgetzan.", completion = "Yes, I gathered that Zilzibin sent you to me.  Your experience in fighting these beasties is priceless; no one to my knowledge has ever dealt with their kind before.  As for Zil's idea that Un'Goro Crater is their heart... perhaps it is.  Un'Goro is a mysterious and dangerous jungle to the west of here.  Perhaps it is also one step closer to figuring out what the silithid are all about.", sourceObjectiveStatus = "unverified-source-field" }
quests[4495] = { id = 4495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Friend", description = "A friend of mine named Iverron usually visits me at the same time every day. The strange thing is that he hasn't been by today at all -- he's several hours late, in fact.\n\nI admit, I am a little worried, {name}. Iverron spends a lot of time over by the cave to the north, and I'm sure you know how dangerous it is there -- spiders, everywhere!\n\nIf you happen to be going that way, though, will you keep an eye out for him?", sourceObjective = "Find Iverron by the cave to the north.", completion = "I'm so glad you found me, {name}. How did you know I was here?", sourceObjectiveStatus = "unverified-source-field" }
quests[4496] = { id = 4496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bungle in the Jungle", description = "My research revealed to me that the silithid are like bees; destroy the queen of the hive, and the rest of should be thrown into disarray.  I'll brew a lure that we'll use to bring out the queen; once summoned, you'll take her down.\n\nFirst though, we need some reagents; we don't want you bungling into the jungle unprepared.  Go west to find the silithid hive in Un'Goro Crater and obtain a scent gland from one of the bugs.  I'll also need some samples of the native Un'Goro soil.", sourceObjective = "Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan.", progress = "Finding a suitable scent gland might take a bit - the gland can't be damaged, but the process of getting one certainly doesn't lend itself to it.  As for the soil, I'd assume it should be easy enough to find.\n\nAnyway, do you have the items I need to make the lure?", completion = "The scent gland, ah yes.  The membrane appears intact - excellent.  The soil, yes, this should work out perfectly.  With my special additions, I should be able to grind all this up into the perfect lure.\n\nGive me a moment to make the lure, {name}.  Once it's ready, we'll be able to enact the next step that may hopefully stop the silithid before they overrun Gadgetzan... and the rest of Kalimdor.", sourceObjectiveStatus = "unverified-source-field" }
quests[4501] = { id = 4501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beware of Pterrordax", description = "Wanted: A skilled fighter to deal with the threat of the Pterrordax that inhabit the Un'Goro Crater. Their numbers are growing, and they are becoming a menace to travelers in the area.\n\nDecrease the population by slaying 10 frenzied pterrordax.\n\nSpeak with Spraggle Frock after completing the task for a reward.", sourceObjective = "Kill 10 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge.", progress = "To tell you the truth, I really wasn't that worried about the strange creatures... Until the day that I saw it written on the side of a large stone.\n\nBEWARE OF PTERRORDAX\n\nWho could have written it? I don't know, but it's too creepy to just ignore!", completion = "I am absolutely terrified of the pterrordax here! Thank you for decreasing their numbers, {name}. Now I might feel safe enough to venture out of Marshal's Refuge.", sourceObjectiveStatus = "unverified-source-field" }
quests[4502] = { id = 4502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volcanic Activity", description = "Being an apprentice to Marvon Rivetseeker, I've learned so much. But he's been gone for such a long time now, so I think I'm going to work on some experiments of my own.\n\nI've been reading about Un'Goro Crater most recently, and about the strange volcanic activity going on in the middle of the crater. I think a lot could be learned if I could just get some of the ash from the elementals there.\n\nDo you think you'd mind collecting some for me, if you are going that way?", sourceObjective = "Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet.", progress = "Is it true that the volcano in Un'Goro is active? I'm sure I could learn a lot with some ash from the volcano, {name}.", completion = "These samples will be perfect for my studies! Thank you, {name}! I promise, you'll be the first one I will tell about my findings.", sourceObjectiveStatus = "unverified-source-field" }
quests[4503] = { id = 4503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shizzle's Flyer", description = "I'm making a flying machine!\n\nI got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death.\n\nSo, will you help me? All I have left to build is the wings, and I was thinking that the webby scales from the pterrordax and diemetradon would be perfect. There's no way I'm going to go up against one of those, but you look pretty tough. Why don't you give it a try?", sourceObjective = "Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge.", progress = "Every great vehicle needs a name... I was thinking I'd call it... Pwned!", completion = "Yes, these scales are perfect. I should be able to get this flyer off the ground with these scales for sure!\n\nThanks!", sourceObjectiveStatus = "unverified-source-field" }
quests[4504] = { id = 4504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Sticky", description = "I'm always looking for a quick way to earn a gold, {name}. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nHead to the tar pits in northern Un'Goro Crater, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. Regular tar just simply isn't sticky enough.\n\nThe plant-like creatures contain chlorophyll in their skin, and mixed with the tar, it's super sticky!", sourceObjective = "Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan.", progress = "Tran'rek's done it again -- this super sticky glue will be all the rage!", completion = "Yes, this tar is just the stuff...\n\nHey, wait a minute, my hands... I can't seem to get them apart...\n\nMaybe this wasn't such a good idea. Oh, but wait! Super sticky tar remover! That's where the real money is!", sourceObjectiveStatus = "unverified-source-field" }
quests[4505] = { id = 4505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well of Corruption", description = "Some may say that I am exceptionally cruel... But truly, it is only a strong desire to see the Horde gain an advantage against the Alliance, in any way possible.\n\nMy newest interest is a moonwell at the Ruins of Constellas, south of here, tended by the Jadefire satyrs. The moonwell, once a symbol of renewal for the insufferable night elves, is now corrupted, and used to bring forth more satyrs.\n\nI have an idea, {name}, and I'd like a sample of the water... for my little feline friend here.", sourceObjective = "Collect a sample of corrupted water from the Jadefire Satyrs' moonwell and bring it to Winna Hazzard at Bloodvenom Post.", progress = "This is of utmost importance. Be on your way, now.", completion = "Very well. We must find a way to use this corruption against our enemies...", sourceObjectiveStatus = "unverified-source-field" }
quests[4506] = { id = 4506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Sabers", description = "This corrupted water can be used to our advantage, {name}. With just a small amount of the water, my kitten doubled in size, and seems to be stronger... somehow. These cats may prove useful...\n\nHere, {name}. Take this cat carrier, and release the kitten inside next to the moonwell in the Ruins of Constellas. Heh, heh... I'm sure you'll be pleased with the results!\n\nReturn the cat to me, and I'm sure I can make it worth your time.", sourceObjective = "Take Winna's kitten to the corrupted moonwell, release it, then bring it back to Winna.\n\nOnce you have returned to Winna, click on the cat to release it to Winna.", progress = "Don't tell me that you can't go back there! Get going!", completion = "Excellent!\n\nThe forsaken will resort to any means necessary to crush the alliance! The use of the corrupted water will surely prove useful in our future efforts...", sourceObjectiveStatus = "unverified-source-field" }
quests[4507] = { id = 4507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pawn Captures Queen", description = "Here's the lure.  Inside the hive network should be a crystal of some sort.  We think the silithid use the crystal as some sort of hive-wide attunement device.  As for where this crystal might be, I'd say try the hatcheries inside the hive.\n\nUsing the lure on the crystal should roust out the queen, but be warned - she will probably be protected by several guards.  Take out the queen and remove her brain.  As icky as that sounds, we desperately need to study it.  Good luck, {name}!", sourceObjective = "Defeat the Gorishi Hive Queen once she is summoned.\n\nBring the Gorishi Queen's Brain to Alchemist Pestlezugg in Gadgetzan.", progress = "Acquiring the queen's brain for our research is absolutely imperative.  From what we have learned, we believe that these silithid are quite possibly being controlled by a malign intelligence.  I shudder to think what could control something as insidious as the silithid, {name}.", completion = "Fantastic, {name}!  We've won quite the victory here today.  It will take some time for us to fully understand what we have here; we'll put it to good use though, don't you worry about that.\n\nAs for the silithid, I genuinely doubt that this was the full extent of their presence.  This is much too clean of a resolution, I'm sorry to say.", sourceObjectiveStatus = "unverified-source-field" }
quests[4508] = { id = 4508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calm Before the Storm", description = "My recent findings and the knowledge we have gained here today needs to reach hands that can quite possibly do something with it.  As resourceful as we are here in Gadgetzan, we can't do this alone.\n\nTake my latest report back to Gracina Spiritmight in Darnassus; she's still at the Temple of the Moon, is she not?  She's got friends who are Alliance bigwigs; if we can get them involved in this {name}, then we just might make it out of this alive.", sourceObjective = "Bring Pestlezugg's Un'Goro Report to Gracina Spiritmight in Darnassus.", progress = "They are fools, {name}!  They cannot even think to look around them for a greater threat; their irrational hatred of the Horde will be the end of us all.  I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!\n\nI'm sorry, you bring news for my attention?", completion = "While I genuinely appreciate this, I am not sure what good it will do us.  The Alliance ignores threats from any source other than the Horde, and even our own leaders here in Darnassus cannot agree on what exactly this threat is.  Fools like Fandral Staghelm theorize that the silithid are nothing like the threat from the ancient past I claim them to be.  His ignorance is only surpassed by his arrogance.\n\nYou have seen the threat yourself, {name}.  We must remain committed to defeating the silithid!", sourceObjectiveStatus = "unverified-source-field" }
quests[4509] = { id = 4509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calm Before the Storm", description = "My recent findings and the knowledge we have gained here today needs to reach hands that can quite possibly do something with it.  As resourceful as we are here in Gadgetzan, we can't do this alone.\n\nTake my latest report back to Zilzibin Drumlore in Orgrimmar; he's still in his place on the upper part of the Drag, is he not?  He's got friends who are high within the Horde; if we can get them involved in this {name}, then we just might make it out of this alive.", sourceObjective = "Bring Pestlezugg's Un'Goro Report to Zilzibin Drumlore in Orgrimmar.", progress = "They are fools, {name}!  They cannot even think to look around them for a greater threat; their irrational hatred of the Alliance will be our undoing.  I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!\n\nI'm sorry, you bring news for my attention?", completion = "While I genuinely appreciate this, I am not sure what good it will do us.  The Horde ignores threats from any source other than the Alliance.  While Thrall himself might take action were the facts presented to him, he is beset on all sides by conflicting advice.  These fools would have us chase our own imaginary tails were they to think it might catch the Alliance unawares!\n\nYou have seen the threat yourself, {name}.  We must remain committed to defeating the silithid!", sourceObjectiveStatus = "unverified-source-field" }
quests[4510] = { id = 4510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calm Before the Storm", description = "{name}, your help has been immeasurable.  The time will come, no doubt, when I'll ask for your assistance against the silithid once more.  We must absorb what we have learned in Un'Goro; I fear that my assumptions that the silithid originated from Un'Goro are now wrong... that indeed there is a far stronger presence somewhere.\n\nTake this note to Idriana at the bank.  She'll give you something from my vault that should be viewed as a token of my gratitude.  Thank you for your assistance, brave {class}.", sourceObjective = "Bring the Bank Voucher to Idriana in the bank of Darnassus.", progress = "Elune'adore, {class}.  What may I do for you today?", completion = "This bank voucher authorizes me to withdraw an item from Gracina Spiritmight's account with us and present it to you.  Congratulations would seem to be in order!", sourceObjectiveStatus = "unverified-source-field" }
quests[4511] = { id = 4511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calm Before the Storm", description = "{name}, we could not have gotten this far without you.  The time will come soon, no doubt, when I'll ask for your help against the silithid once more.  We must absorb what we have learned in Un'Goro; I fear that my assumptions that the silithid originated from Un'Goro are now wrong... that indeed there is a far stronger presence somewhere.\n\nTake this note to Karus at the bank.  He'll give you something from my vault that should be viewed as a token of my gratitude.  Thank you for your assistance, mighty {class}.", sourceObjective = "Bring the Bank Voucher to Karus in the bank of Orgrimmar.", progress = "Zug zug!  What may I help you with today, {class}?", completion = "This bank voucher authorizes me to withdraw an item from Zilzibin Drumlore's account with us and present it to you.  Congratulations would seem to be in order!", sourceObjectiveStatus = "unverified-source-field" }
quests[4512] = { id = 4512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Slime Goes a Long Way", description = "But the thing I've studied most is ooze. I know it sounds odd, but they're all over!\n\nI helped a lady in Menethil find her bag not too long ago--it was eaten by oozes. I've seen members of the Royal Apothecary Society from Undercity collecting samples of the stuff. I want to know why! Where does it come from?\n\nI've heard of more in Felwood. What I need are samples of the oozes there so I can further my research. I'll give you containers, you use them to collect a sample from the deceased creatures.", sourceObjective = "Bring 6 Filled Cursed Ooze Jars and 6 Filled Tainted Ooze Jars to Laris Geardawdle in Ironforge.", progress = "Some of the experiments I've done are fascinating. I think with a little more work, I'll be able to figure out the nature of these creatures and how they play into how life developed on Azeroth... if they even have anything to do with it to begin with.\n\nOne of my biggest theories that isn't well liked is the idea that oozes and slimes are tied to the creation of this planet... almost like they're a secretion of it.\n\nBut I can't prove or disprove it until I get more samples.", completion = "Amazing results, {name}! You got close enough to take a sample of the corrupted things, and managed to look no worse for wear! Thank you. Oh, these samples will be perfect. I can't wait to start testing on them.\n\nIf I'm right, I could be one of the Explorers' Leagues greatest scientists!\n\nThat'll prove to all the dwarves that it wasn't a mistake to allow us gnomes into Ironforge  after the Gnomeregan incident.", sourceObjectiveStatus = "unverified-source-field" }
quests[4513] = { id = 4513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Little Slime Goes a Long Way", description = "I'm going to need more samples, {name}. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure. I do know that these are corrupt... just like Felwood. Which is what makes my realization so important. The oozes seem to adapt... to take on the aspects of the area they're in. I'll need to find samples that haven't been polluted. But where? Where?!\n\nBah! {name}, take these containers just in case you find any on your own.", sourceObjective = "Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.\n\nIf you have trouble finding them, perhaps try to get more clues from Laris.", progress = "So many things to consider. But what does it mean? And how does it affect the lives of the people of Azeroth?", completion = "You've found it? {name}, you are a treasure unto yourself. Your dedication and aid has been magnificent and I could not possibly thank you enough.\n\nPlease, take this for your troubles. I have some work to do, but I'm sure, if you come back at a later time, I'll have need of your services again.\n\nThank you. Thank you so much.", sourceObjectiveStatus = "unverified-source-field" }
quests[4521] = { id = 4521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Guardians", description = "Winterspring lies just beyond Timbermaw, northeast of Felwood. Have you been there?\n\nI have heard that the area is laden with creatures called wildkin. These beasts have been known to guard secrets; secrets of the Night elves.\n\nWe must figure out what may be hidden in Winterspring.\n\nI have heard the ragged owlbeasts can be found just south of the road, and that there are others called raging owlbeasts that may be found in the center of Winterspring. Clear them out, and gain access to the land.", sourceObjective = "Trull Failbane in Felwood wants you to kill 15 Raging Owlbeasts and 15 Ragged Owlbeasts.", completion = "This is excellent news, {name}. With these beasts out of the way, we can begin to adventure further into Winterspring. Are you ready for more?", sourceObjectiveStatus = "unverified-source-field" }
quests[4542] = { id = 4542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message to Freewind Post", description = "Brave traveler, the centaurs have increased their attacks in this area. Freewind Post must know about this renewed harassment immediately! Seek Cliffwatcher Longhorn at Freewind Post to the southeast and give him this urgent message.\n\nBe warned, avoid the Grimtotem Clan nearby... they have been acting strange toward us lately.", sourceObjective = "Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post.", progress = "What do you want, {class}? An urgent message - for me?", completion = "More bad news! These centaurs have gone too far! They raided one of my supply caravans and slaughtered the whole party. This is an outrage, and it will not go unpunished!", sourceObjectiveStatus = "unverified-source-field" }
quests[4561] = { id = 4561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing for Impurities - Un'Goro Crater", progress = "You take a sample of slime from Un'Goro Crater and place some of it into the various tubes and beakers on the table. As things begin to boil and spurt, the slime changes colors. When the process slows down and the liquids calm, you see a small petri dish with your purified Un'Goro slime samples in it along with some other remnants.", completion = "You pick up the petri dish with the slime sample in it. The only way to discern if the samples is pure enough is to open it and examine the contents yourself. Ideally you'll find a sample that fits Chemist Fuely's criteria." }
quests[4581] = { id = 4581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kayneth Stillwind", description = "The druid Kayneth Stillwind sent word to me.  He would like a report of the happenings along our coast and in the forests surrounding Astranaar.  He fears there is a corruption moving through Ashenvale... and he may be right.\n\nHere, take my report to him.  You will find him in the shrine of Forest Song, in the Nightsong Woods to the east.", sourceObjective = "Take Shindrell's Note to Kayneth Stillwind in Forest Song.", progress = "Do you have something for me?", completion = "Ah, Shindrell's report!  Many thanks, {name}.  Shindrell is a fine sentinel, brave and keen.  I must read this for clues of a wickedness I fear is moving through Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[4601] = { id = 4601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give The Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", sourceObjective = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in a frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side...", sourceObjectiveStatus = "unverified-source-field" }
quests[4602] = { id = 4602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give The Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", sourceObjective = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in an almost frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side...", sourceObjectiveStatus = "unverified-source-field" }
quests[4603] = { id = 4603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Sparklematic Action", progress = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", completion = "The Sparklematic 5200 comes to life, lurching to and fro.  Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine's gnomish cleaning agent.\n\nThe Sparklematic 5200 comes to a halt, heralded by a familiar \"ding!\"  The item receptacle of the machine spirals open, revealing a neatly wrapped box." }
quests[4604] = { id = 4604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Sparklematic Action", progress = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", completion = "The Sparklematic 5200 comes to life, lurching to and fro.  Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine's gnomish cleaning agent.\n\nThe Sparklematic 5200 comes to a halt, heralded by a familiar \"ding!\"  The item receptacle of the machine spirals open, revealing a neatly wrapped box." }
quests[4605] = { id = 4605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", sourceObjective = "As quickly as it started, the Sparklematic 5200 comes to an abrupt halt.  A simple \"ding\" is heard from the machine, and the mouth of the machine spirals upward.  Inside the Sparklematic 5200 is a small box wrapped in a little bow.  The machine would appear to wrap an object up after eliminating its grime-encrusted status.  Even if the machine didn't work, at least the item is now wrapped in a pretty box.\n\nWell, there is one way to find out if it cleaned the item or not...", sourceObjectiveStatus = "unverified-source-field" }
quests[4606] = { id = 4606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparklematic 5200!", sourceObjective = "As quickly as it started, the Sparklematic 5200 comes to an abrupt halt.  A simple \"ding\" is heard from the machine, and the mouth of the machine spirals upward.  Inside the Sparklematic 5200 is a small box wrapped in a little bow.  The machine would appear to wrap an object up after eliminating its grime-encrusted status.  Even if the machine didn't work, at least the item is now wrapped in a pretty box.\n\nWell, there is one way to find out if it cleaned the item or not...", sourceObjectiveStatus = "unverified-source-field" }
quests[4621] = { id = 4621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avast Ye, Admiral!", description = "Listen close, sea dawg... the powers of Booty Bay is what keeps us Bloodsail from sailing wheres we like and taking whats we want as rights o' plunder.  Were ye to put a knife to Fleet Master Seahorn, we'd ne'er run afoul of a Booty Bay's vessel.  Were ye to put a knife to Baron Revilgaz, we'd ne'er face the law on their terms.\n\nIf ye are to be an honorary admiral amongst us - yes, ADMIRAL, you'll puts a knife to both of 'em as I've says.  Go now <lad/lass>, and return to me once ye does the deeds.", sourceObjective = "Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale.", progress = "Yer back already, ya blasted tar!  Haves ye done as I've ordered?  Fail us, and ye will be walkin' the plank.\n\nArrrrr...", completion = "Avast ye... Admiral {name}!  Yer a pirate of pirates, lad!\n\nIt warms the cackles of me heart to give ye this hat.  Ye will ne'er find one like it anywheres, and all that gazes upon ye will see that yer an Admiral of the Bloodsail Navy!", sourceObjectiveStatus = "unverified-source-field" }
quests[4641] = { id = 4641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Place In The World", description = "Finally, you are of age, {name}... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.\n\nYes...\n\n<Kaltunk looks you over.>\n\nYou will do nicely.\n\nNo doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.\n\n<Kaltunk laughs.>\n\nReport to Gornek, he should be able to assign a task better suited to a young {class}. You will find Gornek in the Den, to the west.", sourceObjective = "Speak with Gornek. You recall Kaltunk marking your map with his location and mentioning that Gornek resided in the Den, a building to the west.", completion = "Another one of Kaltunk's recruits, hm?\n\nA sorry state of affairs we find ourselves in if this is the best the Horde can produce. No matter. By the time we think you're ready to leave the Valley, you'll be a proud warrior of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[4642] = { id = 4642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Melding of Influences", description = "Here is some encased ooze created from the Felwood samples you recovered. Take the case to Un'Goro Crater and find a pure ooze... the primal variety will do nicely. When you get close enough, release the ooze in the case, and let us see what the two think of one another.\n\nAfter the experiment concludes, bring me a sample of whatever is left over. I will await you here in the Apothecarium.", sourceObjective = "Bring a Merged Ooze Sample to Chemist Fuely in Undercity.", progress = "How goes the experiment, {name}? I will continue to study the samples you've recovered for me--I am starting to see why Lady Sylvanas is so interested in these creatures. If they are truly part of the Old Gods, then who knows how it can be used to our benefit.", completion = "Oh, most excellent, {name}. This is most excellent.\n\nSuch a tale. Who would have thought the two would interact with one another in such a way... I will have to spend more time looking at the environmental issues that cause changes in these creatures.\n\nI will continue my research for now. Perhaps we will speak again soon. Until then, I wish you well.", sourceObjectiveStatus = "unverified-source-field" }
quests[4661] = { id = 4661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing for Corruption - Felwood", progress = "You take a sample of slime from Felwood and place some of it into the various tubes and beakers on the table. As things begin to boil and spurt, the slime changes colors. When the process slows down and the liquids calm, you see a small petri dish with your altered Felwood slime samples in it along with some other remnants.", completion = "You pick up the petri dish with the slime sample in it. The only way to discern if the samples is pure enough is to open it and examine the contents yourself. Ideally you'll find a sample that fits Chemist Fuely's criteria." }
quests[4681] = { id = 4681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Washed Ashore", description = "That beached creature is not an isolated incident here in Darkshore.  There are more along the coastline and even in the water.  I would like for you to investigate another one that we know of; this one was reported to be in the water due west of Auberdine, close to a sunken vessel.  Return to me with anything that you may recover that would aid our research.\n\nAlso, in your travels you may find other creatures.  By all means, if you should discover anything then please bring it to our attention!", sourceObjective = "Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine.", progress = "Once you have investigated the creature's remains in the water to the west of here, I should be able to file a proper report with the Temple of the Moon in Darnassus.  Perhaps then we will be closer to discovering the reason why these unfortunate creatures choose to end their lives beached on the coast of Darkshore.", completion = "You've been a tremendous help here today; we now have a solid chance at unlocking the mystery of why these creatures choose to beach themselves on the coast of Darkshore.  The idea that they might be fleeing the area around Teldrassil is disturbing.  Should you come across others in your travels, please let me know.  Our research here is but in its infancy.\n\nOn behalf of the Temple of the Moon, please accept this as thanks for the effort you have given.  Thank you, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[4701] = { id = 4701, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put Her Down", description = "You have no doubt seen the worgs which the Blackrock orcs command.\n\nIt is curious - no matter how many we destroy, their numbers never dwindle. My scouts have reported that the worgs are bred, trained, and ultimately exported from Blackrock Spire: capital city of the Blackrock orcs. You must travel to Blackrock Spire and discover the source of this menace. Discover... and destroy.\n\nGood luck, {name}. May Cenarius protect you...", sourceObjective = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg.", completion = "Do not dwell upon her suffering, {name}. The beast was corrupt - a product of dark magic. You have done the Alliance a great service and you shall be rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[4721] = { id = 4721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Guardians", description = "Runners have returned from Winterspring with reports that there is a series of small caves in the southern area of Winterspring. It seems that there are wildkin situated in the area around these caves. If there is something valuable that they are guarding, I believe that this is the place we will find it.\n\nYou will find these to be more of a challenge than the previous types, {name}. The creatures seem to have gone mad from exposure to the very thing that they strive to protect.", sourceObjective = "Trull Failbane in Felwood wants you to hunt 10 Berserk Owlbeasts in Winterspring.", completion = "Hard work is something I have great respect for, {name}. Now we can move forward with our plans for Winterspring.", sourceObjectiveStatus = "unverified-source-field" }
quests[4722] = { id = 4722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Turtle", description = "You find a corpse of a sea turtle that had beached itself on the coast of Darkshore some time ago.  It has been scavenged by the murlocs who have encamped themselves around the creature's remains.  Still, there appear to be some suitable samples left on the creature's remains that Gwennyth Bly'Leggonde in Auberdine might be able to make use of.", sourceObjective = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.", progress = "Hello {name} - do you have any discoveries of creatures that have washed ashore to report on?", completion = "Another discovery for us to research - well done {name}!  These remains will be properly studied once they get to Darnassus.  Please accept this small honorarium in exchange for the remains you have provided for our study.", sourceObjectiveStatus = "unverified-source-field" }
quests[4723] = { id = 4723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Creature", description = "The remains of a giant thresher - much larger than one you'd expect to find in Darkshore - lie beached on the coast of the Mist's Edge.  How this creature came to be here is unknown; the group of murlocs that now feast off the carcass of it seem to be much too weak, even in large numbers, to have brought down the beast. \n\nWhile some of it has been picked clean, enough of it remains to take a sample for Gwennyth Bly'Leggonde in Auberdine to study.", sourceObjective = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.", progress = "Perhaps one day we'll find a means to prevent these poor creatures from ending their lives needlessly on the coast of Darkshore.  Until then, we must continue our research!\n\nGreetings {name} - what news do you bring?", completion = "Another discovery - well done {name}!  These remains will be properly studied once they get to Darnassus.  Please accept this small honorarium in exchange for the remains you have provided for our study.", sourceObjectiveStatus = "unverified-source-field" }
quests[4724] = { id = 4724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pack Mistress", description = "Some say the worg controlled by the Blackrock orcs are the creation of a supernatural force. Others say they are not true worg but instead a breed of demon dog, granted to the orcs by a fallen pit lord.\n\nThe truth is far less contrived but every bit as frightening. The worg of Blackrock come from Halycon and her mate. Halycon is the gigantic den mother of the worg. Her mate? Nobody has ever lived to tell the tale of that one.\n\nStrike at the heart of the worg. Destroy Halycon... and {name}, watch your back.", sourceObjective = "Slay Halycon, pack mistress of the Bloodaxe worg.", completion = "Rabid pups? Gizrul the Slavener? And you live to tell the tale?! Incredible! A tribute well earned!", sourceObjectiveStatus = "unverified-source-field" }
quests[4725] = { id = 4725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Turtle", description = "More sea turtle remains lie beached along the coastline.  This particular set has an abandoned carriage attached to the turtle's shell.  Perhaps this creature was driven to the shoreline by unknown beings rather than beaching itself as some of the other remains suggested.  Greymist murlocs now make the remains of this creature their home, feasting off the carrion.\n\nIn the carriage, you find a box with strange markings on it; perhaps Gwennyth Bly'Leggonde in Auberdine can make sense of it.", sourceObjective = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.", progress = "It is a pleasure to see you again, {name}.  We are making great strives in uncovering the mystery of why majestic sea creatures beach themselves on the Darkshore coastline, but with every question answered, two more are raised it seems.\n\nAre you here to offer us more aid in our research?", completion = "I have heard of the kinds of carriages found on the back of the turtle you found.  Those I do believe are naga carriages, used both in battle and in transportation of their supplies on to land.  The markings on the box you found are of the naga; this would explain their invasive presence in far-northern Darkshore.\n\nI will send this box to Darnassus along with the rest of your discoveries.  This is for you - thank you again for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[4726] = { id = 4726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broodling Essence", description = "I have been studying the dragonkin of the Burning Steppes for weeks, and I think I've finally had a breakthrough!  I created a device--I call it the Draco Incarcinatrix 900.  It can capture the essence of dragon whelp broodlings!\n\nOr, at least I think it can.\n\nHere, take the device and zap a broodling in the Burning Steppes with it.  While it's under the device's effects, defeat the broodling and its essence should be released.\n\nIf it is, then splendid!  Bring me back samples so I can study them!", sourceObjective = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.", progress = "Do you have the broodling essence, {name}?  I can't wait to study it.\n\nAnd besides that... my patron is not the type of person you want to disappoint.", completion = "It worked!  You got the essence!  Well done, {name}!  Well done!\n\nThis essence will be invaluable in my research.  I hope to one day learn how to capture living dragons whelps, or perhaps capture their eggs.  If I could find a way to do that, then I would be the envy of dragon scholars around the world!\n\nMy employer would also be happy, and as I said before, he's someone you want to keep happy...", sourceObjectiveStatus = "unverified-source-field" }
quests[4727] = { id = 4727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Turtle", description = "The skeletal remains of a sea turtle lie in the sand of the northern Darkshore beaches.  The Greymist murlocs have either not found this carcass, or perhaps they have and are shying away from it for some unknown reason.  Regardless, there is enough of the turtle left to take a sample back to Gwennyth Bly'Leggonde in Auberdine for the Temple of the Moon to study.", sourceObjective = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.", progress = "Hello once again {name} - have you found any more beached creatures that the Temple of the Moon should know about?", completion = "It is interesting that the murlocs were not present at this site; we will keep this in mind as we study this creature's remains!  Thank you for your effort, {name}; the Temple of the Moon would like for me to give you this, as compensation for your time.", sourceObjectiveStatus = "unverified-source-field" }
quests[4728] = { id = 4728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Creature", description = "The corpse of what appears to be some sort of giant sea mammal lies partially gutted on the beach.  A wheelbarrow and various tools lie abandoned by this enormous beached sea creature, as though an attempt to study it had been made previously.  Though murlocs have scavenged this beast, enough of it remains to gather a suitable sample for Gwennyth Bly'Leggonde in Auberdine.", sourceObjective = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.", progress = "Greetings once again, {name}!  What brings you back to Auberdine?  Are you here to report on another discovery, perhaps?", completion = "Ah, I believe you discovered one that was originally being examined by the Explorer's League.  They have a presence here in Darkshore, and they had mentioned that they were studying one of the beached creatures until they were chased out by the murlocs.  You appear to have succeeded where we both have not.  Please - accept this honorarium on behalf of the Temple of the Moon.", sourceObjectiveStatus = "unverified-source-field" }
quests[4729] = { id = 4729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kibler's Exotic Pets", description = "You're probably wondering what I'm doing out here. Look at the cages! Ain't it obvious?\n\nI'm an animal lover, first and foremost, but a salesman by trade. I track down exotic animals for the rich and famous and domesticate the beasts so they behave as proper pets.\n\nNow you're probably wondering, \"What can I do for you, Kibler.\" The answer is simple: Take this here beast cage and find me some worg pups. For that, I'll domesticate a worg for you!", sourceObjective = "Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.", progress = "<Kibler is busy arguing with Opus.>", completion = "You got 'em at the perfect time, {name}. Any later and they'd be untrainable! Gimmie a minute and I'll have the little fella ready for you to take home.", sourceObjectiveStatus = "unverified-source-field" }
quests[4730] = { id = 4730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Creature", description = "The half-devoured corpse of what might have been a giant sea mammal lies on the beach.  A band of murlocs, stronger than those found closer to Auberdine, have taken up residence around the fallen creature.  Enough of the creature remains that a suitable sample of its bones could be delivered to Gwennyth Bly'Leggonde in Auberdine.", sourceObjective = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.", progress = "Hello again, {name}!  Are you here to report on another discovery?", completion = "The bones you have are from gentle sea mammals that are known to inhabit the waters surrounding the base of Teldrassil.  They had never been known to violently beach themselves like the threshers had been known to.  Why would these creatures do this, I wonder?  Well, perhaps the study of their remains will bear the fruits of knowledge that we seek.\n\nAgain, thank you for your aid.  Please accept this honorarium from the Temple of the Moon.", sourceObjectiveStatus = "unverified-source-field" }
quests[4731] = { id = 4731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Turtle", description = "Another set of sea turtle remains lie beached on the coastline.  This set of remains has an abandoned carriage half buckled to the turtle's shell.  Perhaps this creature was driven to the shoreline by unknown beings rather than beaching itself as some of the other remains suggested.  Powerful Greymist murlocs have made the carcass of this creature their current home.\n\nIn the carriage, you find a box with strange markings on it; perhaps Gwennyth Bly'Leggonde in Auberdine can make sense of it.", sourceObjective = "Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine.", progress = "Hello again, {name}.  The work you have done on behalf of the Temple of the Moon has been outstanding.  Are we to be blessed with more of your effort on our behalf?", completion = "I have heard of the kinds of carriages found on the back of that turtle.  Those I do believe are naga carriages, used both in battle and in transportation of their supplies on to land.  The markings on the box you found are of the naga; perhaps the creature you discovered was killed as it was heading further south... to Ashenvale maybe?\n\nI will be sure to send this box to Darnassus with the rest of your discoveries.  This is for you - thank you again for your assistance.", sourceObjectiveStatus = "unverified-source-field" }
quests[4732] = { id = 4732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Turtle", description = "You find a corpse of a sea turtle that had beached itself on the coast of Darkshore some time ago.  It has been picked nearly clean by Greymist murlocs, the very ones who now have encamped themselves around the creature's remains.  Still, there appear to be some suitable samples left on the creature's remains that Gwennyth Bly'Leggonde in Auberdine might be able to make use of.", sourceObjective = "Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine.", progress = "Greetings once again {name} - do you have any more discoveries to report to the Temple of the Moon?", completion = "You've found even more beached creatures, {name}?  Sea turtles were commonly found frolicking along the base of Nordrassil before it was destroyed.  With the birth of Teldrassil, however, these creatures have been seen in ever decreasing numbers.  Some, as we have discovered, end their lives here for some unknown reason.\n\nYour aid will perhaps unlock the mystery before us.  Please accept this in exchange for the remains you have provided for our study.", sourceObjectiveStatus = "unverified-source-field" }
quests[4733] = { id = 4733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beached Sea Creature", description = "The remains of what appear to be a giant thresher have washed ashore on the rocky inlet of the Twilight Shore.  The thresher is several times larger than any of the other threshers spotted in these parts.  Wherever it came from, this creature would not seem to have been native to Darkshore.\n\nThough the creature has been picked apart in places, enough of it remains to gather a suitable sample for Gwennyth Bly'Leggonde in Auberdine.", sourceObjective = "Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine.", progress = "Thanks be to Elune - I am glad to see you again, dear {name}.  The Temple of the Moon's work on the strange beaching phenomena continues here in Darkshore.  Might you have anything additional to offer us?", completion = "The dimensions of the thresher you mention are mind-boggling.  Even the eldest of the threshers in this region grow to only a fraction of that size.  While some larger ones were known to be close to Teldrassil, their numbers have declined steadily.  I cannot help but wonder if these creatures beaching themselves here are somehow related to this.\n\nWhile we analyze the bones you have brought us, please accept this on behalf of the Temple of the Moon.  Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4734] = { id = 4734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Freezing", description = "{name}, I've been working hard on a new device, the eggscilloscope!  It's designed to project a burst of cold energy at the egg of a black dragon... and freeze it solid!  Can you test it for me?\n\nI heard that high up in Blackrock Spire, the dragons have a rookery where they hatch their eggs.  That's where you'll have to go to test the eggscilloscope, and then let me know how it worked!\n\nAnd don't worry.  Frozen dragon eggs should be harmless.  It's the unfrozen ones you have to worry about!", sourceObjective = "Use the Eggscilloscope Prototype on an egg in the Rookery of Blackrock Spire.", progress = "{name}, did you test the eggscilloscope?", completion = "It worked?  Splendid!  I knew it would!\n\nWhile you were gone I was working on a new version of the eggscilloscope.  This one has a much longer range.\n\nHere, you can have one in case you go back to Blackrock Spire.", sourceObjectiveStatus = "unverified-source-field" }
quests[4735] = { id = 4735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg Collection", description = "{name}, I'm finally ready for real samples of dragon eggs!  Here, take this collectronic module.  It's designed to extract a dragon egg and prepare it for transport.  Go back to the Rookery and use the module to collect eggs.\n\nAnd don't forget to freeze them first, or they might hatch before you can collect them!\n\nWhen you have enough eggs, bring them to me!", sourceObjective = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes.", progress = "Do you have the eggs, {name}?  My patron heard you were collecting them for me, and is very eager to get his hands on them!", completion = "Wow, you got them!  The collectronic module worked!  I'm a genius!\n\nThank you, {name}.  My patron will be very pleased to get these eggs...", sourceObjectiveStatus = "unverified-source-field" }
quests[4736] = { id = 4736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Menara Voidrender", description = "Ah, hello, {name}. You're progressing well in your training. So well in fact that I think you should be rewarded for your hard work--and for not becoming corrupted by the arcane yet.\n\nIf you're interested, seek out Menara Voidrender in Ratchet. She is currently staying at Strahad Farsan's tower overlooking the town.\n\nShe's not very friendly, {name}, so don't expect any praise. But if you work hard, she'll make sure you're taken care of.", sourceObjective = "Speak to Menara Voidrender in the Barrens.", completion = "Ah, Briarthorn sent you. Good. Then word does reach far enough to find future students. This pleases me.\n\nIt is typical of our kind, {name}, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.\n\nI feel you've learned a great many things, and if you are willing, I would help you create tools to compliment your skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[4737] = { id = 4737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Menara Voidrender", description = "Hmph, still you strive to become more powerful. I say it's only time before the corruption and addiction takes hold of you and you become a slave to that which you seek to gain power over.\n\nPfah! A fool you are! Time will prove me right--nothing else... just time.\n\nBut it seems that not all agree with Zevrost. It seems Menara would create tools for you to become more powerful and to harness your strength. If you're interested, then go to Ratchet in the Barrens. She is there overlooking the town.", sourceObjective = "Speak to Menara Voidrender in the Barrens.", completion = "Ah, Zevrost sent you. Good. Then word does reach far enough to find future students. This pleases me.\n\nIt is typical of our kind, {name}, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.\n\nI feel you've learned a great many things, and if you are willing, I would help you create tools to compliment your skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[4738] = { id = 4738, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Menara Voidrender", description = "Let us be clear about one thing, {name}: I don't feel you are ready for such responsibilities. I don't think aiding in the creation of any item of power is something a novice should ever be involved in; especially one so untested.\n\nBut that's not my decision. The powers that be, or at least the ones that do wish to impart such gifts upon you get to decide that.\n\nIf you're interested in learning more, I suggest you seek out Menara Voidrender in Ratchet. She usually resides in the tower above the port town.", sourceObjective = "Speak with Menara Voidrender in the Barrens.", completion = "Ah, Demisette sent you. Good. Then word does reach far enough to find future students. This pleases me.\n\nIt is typical of our kind, {name}, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.\n\nI feel you've learned a great many things, and if you are willing, I would help you create tools to compliment your skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[4739] = { id = 4739, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of Menara Voidrender", description = "{class}! Yes, you!\n\nYou don't have all the accoutrements, but it's plain to see you're ready--the air around you exudes greater confidence. Yes, I see it now.\n\nMenara Voidrender would teach you a few things if you feel you're ready. She spends her time tutoring younger students in the arcane. She even gives gifts to those who pass her tests.\n\nGo to Ratchet in the Barrens if you're interested. She's above the city in Strahad's tower.", sourceObjective = "Speak to Menara Voidrender in the Barrens.", completion = "Ah, Kaal sent you. Good. Then word does reach far enough to find future students. This pleases me.\n\nIt is typical of our kind, {name}, to band together, regardless of race. It is especially important since those we deal with most do not discriminate in their malice if we fail to appease them or control them properly.\n\nI feel you've learned a great many things, and if you are willing, I would help you create tools to compliment your skills.", sourceObjectiveStatus = "unverified-source-field" }
quests[4740] = { id = 4740, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Murkdeep!", description = "Attention!\n\nA reward is being offered for the death of the murloc \"Murkdeep\".  This foul beast is known to be responsible for the death of at least one Sentinel, and is suspected of causing the sinking of at least two cargo vessels in the waters off Darkshore!\n\nMurkdeep was last spotted at a hutted murloc camp south of Auberdine, and is thought to be protecting the huts there.  Reward claims for this bounty should be claimed with Sentinel Glynda Nal'Shea in Auberdine.\n\nThe Auberdine Village Council", sourceObjective = "Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.\n\nReport the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine.", progress = "Greetings {class} - what may the Sentinels assist you with today?  Perhaps you are here to inquire about the bounty on Murkdeep?", completion = "Well, looks like you're here to more than just inquire!  The citizens will be delighted to know that tonight they will sleep a little bit more soundly and safer.\n\nYou've acted as the executioner of justice for the people of Auberdine today, {name}.  For that, I would like to offer you this as a suitable reward... for a true hero of the Auberdine people.", sourceObjectiveStatus = "unverified-source-field" }
quests[4741] = { id = 4741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Guardians", description = "In the northern areas of Winterspring, the Wildkin grow even more ferocious. We must continue our measures there.\n\nHunt the moontouched owlbeasts in Winterspring, and explore the area they inhabit.\n\nThis is dangerous ground, but I know that you will be able to handle the challenge. Return to me after you have slain 13 of the wildkin.", sourceObjective = "Trull Failbane in Felwood wants you to hunt 13 Moontouched Owlbeasts.", progress = "Don't tell me that you're too scared! Get going!", completion = "I sense that you are enjoying your work. And I believe that we are onto something here.", sourceObjectiveStatus = "unverified-source-field" }
quests[4742] = { id = 4742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seal of Ascension", description = "As you can see, the unadorned seal has three empty sockets. Each of those sockets must be filled with a gemstone representing the leadership's command. Finally, Overlord Wyrmthalak, master of the lower citadel, must forge the seal in the flames of the Black Dragonflight.\n\nUnderstand this, mortal: the chance that one of the three generals of the lower citadel would carry a gemstone at any given time is rare. You must be vigilant in your quest. Remain determined!", sourceObjective = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\n\nThe Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak  of the Bloodaxe.", progress = "Courage and patience above all else, mortal!", completion = "<Vaelan's image blurs for a moment.>\n\n<The pieces that you had collected have disappeared.>\n\nThe Unforged Seal of Ascension is now ready. It is time for the final step.", sourceObjectiveStatus = "unverified-source-field" }
quests[4743] = { id = 4743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seal of Ascension", description = "Few of the black dragonkin, outside of those in the upper citadel, have the ability to forge the seal with their own flaming breath. Wyrmthalak is one such dragonkin, but his will is unbreakable.\n\nYou must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find an ancient drake known as Emberstrife. You must break his will, {name}. Break it and use this orb on his weakened form. You will have scant seconds to control his mind and fan the flames that will forge the seal.", sourceObjective = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\n\nIt is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!", progress = "Waste no time, mortal. Nefarian works feverishly to unleash his evil upon our world.", completion = "Stand steady while I cast the final invocation of protection.\n\n<Vaelan's eyes turn to twin orbs of flame.>\n\nThe Seal of Ascension is complete...\n\nKnow this, I have imbued the artifact with some powerful protective wards. In your darkest hour, when all appears to be lost, the might of the red flight will be at your disposal.", sourceObjectiveStatus = "unverified-source-field" }
quests[4761] = { id = 4761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thundris Windweaver", description = "Your scouting of the furbolg camp is information that Thundris Windweaver should be made aware of.  He graciously serves as the elder of Auberdine, offering sage and just stewardship of the day to day affairs of the village.  Please - share with him your findings to date on the furbolg situation.\n\nI believe he has some ideas of his own on the reasons behind their corruption.  Perhaps you can work with him to enact a plan to restore the balance of nature here!", sourceObjective = "Speak with Thundris Windweaver in Auberdine.", completion = "Well met, {class}.  Your scouting of the furbolg situation comes at a fortuitous time for us in Auberdine.  For some time we have dealt with not only forest dwellers who are now openly hostile to our presence, but also the outright corruption of the forest itself.  Hopefully you might be able to lend Auberdine aid during these troubling times.", sourceObjectiveStatus = "unverified-source-field" }
quests[4762] = { id = 4762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cliffspring River", description = "The Cliffspring River has begun turning foul and corrupted.  It empties into the Mist's Edge, and I fear the wash will affect Auberdine soon.  I suspect the Blackwood furbolgs up-river are the cause of the taint, but I also suspect that they aren't the true root of it.\n\nTake this sampling tube and go to the mouth of the river to our north.  Proceed inland to the first waterfall and draw a sample from the pool there.  You'll see a bridge overhead.  Once you have a sample, return to me in Auberdine.", sourceObjective = "Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.\n\nReturn to Thundris Windweaver in Auberdine with the Cliffspring River Sample.", progress = "The pollution of the Cliffspring River is but the start of an alarming trend here in Darkshore.  The sample you provide will help us formalize a plan... a plan of attack, I am starting to suspect.", completion = "It's no surprise how tainted this water is, but just look at how putrid it is becoming!  It would seem that action is needed sooner than later, eh {name}?\n\nTo our east is Felwood; it is the real source of this corruption, one that I have seen in times past.  I predict this sample will confirm this.  We might be able to enact a cure for it here, but in order to even try we will need assistance.  When that time comes {name}, I hope you will be able to give the aid we need.", sourceObjectiveStatus = "unverified-source-field" }
quests[4763] = { id = 4763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackwood Corrupted", description = "We've learned that a source of furbolg corruption is from the satyr.  They hold sway via talismans that they channel magic through.  If the furbolg have a chance at salvation, we must lure out the satyr corruptor and take that talisman!\n\nFill this bowl at our moonwell and take samples of the furbolgs' food from their northern camp.  Mix them and place it near the bonfire by the river; any furbolgs who eat will be cleansed just long enough to lure out the satyr corruptor... who then you must slay!", sourceObjective = "Fill the Empty Cleansing Bowl at the Auberdine Moonwell.\n\nGather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.\n\nMix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.\n\nTake the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.", progress = "The Talisman of Corruption is a sinister device that only serves to pervert the balance of nature.  When you obtain this item from whatever satyr is tormenting the furbolgs and bring it to me for disposal, we will have won a great victory this day!", completion = "We have just begun this war to reclaim our forest from the forces of corruption, but a battle this day has been won!  {name}, the people of Auberdine owe you a debt of gratitude that will never be easily repaid.  Please accept this along with our thanks.  What we have learned here today may one day free our furbolg friends from the shackles of torment permanently.", sourceObjectiveStatus = "unverified-source-field" }
quests[4764] = { id = 4764, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomrigger's Clasp", description = "There is a chamber, high in Blackrock Spire, that was once called the Hall of Fortune.  It was where the Dark Iron dwarves kept their relics, trophies and objects of art.\n\nThat was long ago.  It is said the hall has collapsed and is now used for... less savory tasks.  But I believe some old dwarven relics may still be found there.\n\nOne such relic is Doomrigger's clasp, with a surface so encrusted with rare gems that it was said to make weep any dwarf who gazes upon it.\n\nThat clasp, {name}, is your goal.", sourceObjective = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", progress = "Do you have the clasp, {name}?  My patron will pay very handsomely for it.", completion = "You found it!  So the rumors were true!\n\nThank you, {name}.  My patron, Count Remington Ridgewell, will be quite pleased to see this addition to this collection.", sourceObjectiveStatus = "unverified-source-field" }
quests[4765] = { id = 4765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Ridgewell", description = "I have packaged Doomriggers Clasp into a crate, suitable for shipment to Stormwind.  {name}, you have been extremely helpful -- can I ask you for one last favor?\n\nDeliver the crate to Count Remington Ridgewell.  You will find him in the Keep of Stormwind.  I am sure he'll be very pleased to see what you have for him.", sourceObjective = "Bring Ridgewell's Crate to Count Remington Ridgewell at Stormwind Keep in Stormwind.", progress = "I was told a messenger would come.  One with a gift from Blackrock Spire.\n\nAre you he?", completion = "Ah, so you are he!  You have my thanks, {name}.  And... if you didn't already know... the gratitude of a noble in the house of Ridgewell is nigh worth a king's ransom.", sourceObjectiveStatus = "unverified-source-field" }
quests[4766] = { id = 4766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mayara Brightwing", description = "An agent of mine, Mayara Brightwing, was sent to the Burning Steppes to scout the ruined city of Thaurissan.  That destroyed city of the Dark Iron dwarves may hide objects of great value... objects that would fit nicely into our family museum.\n\nMayara says she found something and will need aid in retrieving it, but it is not in Thaurissan.  Instead, a foray into Blackrock Spire will be required.\n\nI do not know the details, but if interested then speak with Mayara in the Burning Steppes.", sourceObjective = "Speak with Mayara Brightwing at Morgan's Vigil in the Burning Steppes.", completion = "You came from Stormwind?  Wonderful -- I know of an object of art that Remington would kill to have in his museum, but extracting it won't be easy.\n\nThat's where you come in.", sourceObjectiveStatus = "unverified-source-field" }
quests[4767] = { id = 4767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wind Rider", description = "I've been tasked to recruit more wyverns for the master wind riders. Their numbers are growing and I myself hope to become a wind rider one day. However, we cannot train enough wyverns to keep up with the demand. Perhaps you can help me, {name}.\n\nI need you to travel to Highperch to gather some wyvern eggs. From here, head northwest along the canyon walls to a ramp that will lead you into Highperch. Be careful, wyverns are very protective over their eggs and they will not be kind to intruders.", sourceObjective = "Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post.", progress = "{name}, have you retrieved the wyvern eggs that I seek? I'm really anxious to start my wind rider training!", completion = "Perfect! With these eggs I hope to take the next step to become a wind rider. Here is a token of my appreciation; may good hunting always shine upon you, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[4768] = { id = 4768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkstone Tablet", description = "The Darkstone Tablet holds the writings of the long-dead dwarf Urheld Darkstone.  An alchemist of great skill, he was thought insane by his contemporaries and, hence, did not share his research.\n\nBut he did etch it onto tablets, and I believe one such tablet lies in Blackrock Spire, in a chamber once named the Hall of Fortune.  I know not what it is now called, for few enter Blackrock and return.\n\nBut if you are willing to brave its dangers and return to me with the tablet, your reward will be great.", sourceObjective = "Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath.", progress = "Have you found the Tablet, {name}?  I yearn to delve into its secrets.", completion = "Excellent.  The formulae etched into this tablet will consume days of research, but I am confident such research will bear sweet fruit.\n\nThank you, {name}.  You have been invaluable to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[4769] = { id = 4769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vivian Lagrave and the Darkstone Tablet", description = "Vivian Lagrave sent me word from Kargath, in the Badlands.  Through her studies, she believes there is an ancient text within Blackrock Spire that would benefit our research.  To confirm this, she will need someone to extract the text from the spire.  No easy task.\n\nIf interested, then speak with Vivian in Kargath.", sourceObjective = "Speak with Shadowmage Vivian Lagrave.", completion = "It is true.  I believe there is a tablet held within Blackrock Spire, a tablet that contains old alchemical recipes.  I am glad you are here, for I need help in retrieving the tablet.\n\nMake yourself comfortable, and I will explain further.", sourceObjectiveStatus = "unverified-source-field" }
quests[4770] = { id = 4770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Homeward Bound", description = "Please help me, {class}! I've been hiding here in Highperch for some time now and it's been days since I've seen a friendly face. I came here to study the wyvern and I think I got a little too close. After being chased away from one of the nests I got lost.\n\nI need to get back to Whitereach Post! Motega does not know that I am missing and will be furious to know that I ventured into Highperch by myself.\n\nWhitereach Post is just east of here... please take me there!", sourceObjective = "Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post.", completion = "What!? If I knew that Pao'ka Swiftmountain was going to snoop around Highperch, I would have chained him to a totem! His father was reluctant allowing him to come with me to Thousand Needles. We came here to study the different creatures that inhabit these beautiful lands.\n\nI appreciate the help you have shown Pao'ka. I hope this covers any misfortunes this deed has cost you.", sourceObjectiveStatus = "unverified-source-field" }
quests[4771] = { id = 4771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dawn's Gambit", description = "I've placed Dawn's Gambit in the container you brought to us, the one that held the dragon eggs.  Your job is to bring it deep within the Scholomance.\n\nThe undead mage Vectus leads a team of Scourge scholars... place Dawn's Gambit in their chamber, called the \"viewing room.\"  It will then react with the undead found there and, with a little luck, destroy them!\n\nAfter that, defeating Vectus shouldn't be a problem.  Right?", sourceObjective = "Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink.", completion = "You did it!  Vectus is defeated!  And Dawn's Gambit... did it work?\n\nHm... maybe my device wasn't the success I had hoped, but I'm glad you were able to handle things anyway.  Well done, {name}!\n\nThe Argent Dawn, and the good people of Azeroth, are in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[4781] = { id = 4781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components for the Enchanted Gold Bloodrobe", description = "Your next task is as simple as your first, but will require you to seek out aid.\n\nI require gold thread for the embroidery of the cloak, but gold thread is not easy to come by, and very few know how to make it. Fortunately, one who is loyal to our cause knows its secrets and is willing to help those rising in our ranks.\n\nBring a gold bar to Xizk Goodstitch in Booty Bay. He is a master tailor and will be happy to spin the thread for you. Gold bars are smelted by skilled miners. Ask a miner for help.", sourceObjective = "Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale.", progress = "Gold bars, yes... yes. Bring me one and we'll see what we can do about spinning some thread for you. Until then, I would suggest you focus your efforts on becoming more powerful. Your toughest trials are still ahead. And trust me... you'll wish you were more prepared, regardless of how powerful you think you might be.", completion = "Perfect, {name}. I'm glad you could find a miner to help you out so quickly. Or did you do this work yourself? Either way, you've done well. This will be perfect for the thread.\n\nIt will take some time to create the stuff, so you'll have to come back--I actually send it off to some princess who we have locked in a tower who's only job is to spin gold thread... no, seriously. I mean it... okay, not really.", sourceObjectiveStatus = "unverified-source-field" }
quests[4782] = { id = 4782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components for the Enchanted Gold Bloodrobe", description = "Return to Menara, tell her it'll take some time, but I'll make sure to come through for her... and you. Tell her to have you finish gathering the rest of your components--I should have the thread done by then. You can return and pick it up then.\n\nGood luck, {name}. Oh, and say hello to Strahad for me while you're there. That old coot... putting a tower right there next to Ratchet... crazy.", sourceObjective = "Return to Menara Voidrender in the Barrens.", completion = "Good, you've returned, {name}. And where is the thread?\n\nAh, I understand. That is acceptable. The goblin and his brother have not failed us yet--I suppose it is understandable that he did not have it prepared right then. So be it... we have other things we can attend to in the meantime.\n\nAre you prepared for the next step?", sourceObjectiveStatus = "unverified-source-field" }
quests[4783] = { id = 4783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components for the Enchanted Gold Bloodrobe", description = "The next components are found in Desolace, far to the west of the Barrens and even the Stonetalon Mountains.\n\nThere, chaos still reigns after the Sundering. Both your strength and cunning will be tested there--you will face creatures of hatred and also of the Burning Legion.\n\nFrom the Hatefury satyr in the northeast, bring me their blood. From the lesser infernals in Mannoroc Coven, bring me a lesser infernal stone.\n\nWe will use both in the construction of your robe.", sourceObjective = "Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens.", progress = "Desolace is not a kind area: naga, giants, satyr, the Burning Legion... all of those and warring centaur clans all make the land dangerous if you're not careful.\n\nLike I said before, it will not only test your strength and cunning, but also your patience. Be wary in those lands, {name}.", completion = "Excellent, {name}. These will do nicely. I will prepare them now while you move on to your last two components. Are you ready?", sourceObjectiveStatus = "unverified-source-field" }
quests[4784] = { id = 4784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Components for the Enchanted Gold Bloodrobe", description = "I need only three things now, {name}, then we can finish your robe.\n\nFirst, the fine gold thread Xizk is making for you. Return to him in Booty Bay and get it.\n\nSecond, bring me two smoldering coals from the fire elementals in the Arathi Highlands. If I recall correctly, they are to the west, near Thoradin's Wall.\n\nFinally, a soul shard created by you.\n\nAfter you have all the components, return here to the tower and I will complete the robe for you.", sourceObjective = "Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens.", progress = "Soon, {name}. I promise you. The robe will be more than adequate for your needs and certainly give you an edge over your opponents.", completion = "Excellent, {name}! The components are gathered and we are ready.\n\nI trust you will be pleased.", sourceObjectiveStatus = "unverified-source-field" }
quests[4785] = { id = 4785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fine Gold Thread", sourceObjective = "Here you go, {name}. And please tell Menara we say hello.\n\nWe expect great things of you. Perhaps when the Legion falls to its knees, your name will be spoken aloud and in praise of your power. I can't wait!", sourceObjectiveStatus = "unverified-source-field" }
